class CoordinatorUpTest(unittest.TestCase):
    """How the coordinator's session is recorded (hansa notify on, notify-launch) and started again (hansa up),
    with the process readers, tmux and exec faked: the tests run with neither tmux nor claude."""
    setUp, say = UpTest.setUp, UpTest.say  # UpTest's desk and environment, the coordinator's part not faked

    SESS = {"pid": 4242, "start": "boot:77"}
    KEY = "sk-desk-secret-123456"
    IDENTITY = "session-identity-0123456789"

    def own_folder(self):
        folder = self.tmp / "own folder"
        folder.mkdir(exist_ok=True)
        return folder

    def notify_on(self, argv, folder=None, sess=None, flags=(), **env):
        """hansa notify on from a session (SESS unless given) whose claude ran with argv in folder: what it printed,
        what it recorded, and whether it read the session's process."""
        folder = str(self.own_folder()) if folder is None else folder
        os.environ.update(env)
        from hansa import up
        with unittest.mock.patch.object(notify, "turn_on", return_value="hansa now posts to this session"), \
                unittest.mock.patch.object(notify, "session_here", return_value=dict(sess or self.SESS)), \
                unittest.mock.patch.object(up, "proc_args", return_value=argv) as args, \
                unittest.mock.patch.object(up, "proc_cwd", return_value=folder), \
                unittest.mock.patch.object(up, "record_tmux", return_value={"server": ["-L", "default"],
                                                                            "session": "work"}):
            said = self.say("notify", "on", *flags)
        return said, up.read_coordinator(self.desk), args

    def test_notify_on_records_the_sessions_exact_start_without_its_conversation_or_identity(self):
        argv = ["claude", "--continue", "--name", "desk b", "--model", "opus[1m]", "--effort", "max",
                "--permission-mode", "auto", "--session-id", "u-1", "--messaging-socket-path", "/run/x.sock",
                "-r", "abc", "--fork-session", "--append-system-prompt", ""]
        said, rec, args = self.notify_on(argv, PATH="/saved/bin:/usr/bin", LANG="C", HANSA_CLAUDE="/opt/claude",
                                         ANTHROPIC_API_KEY="caller-key", CLAUDE_CODE_SESSION_ID=self.IDENTITY,
                                         UNRELATED="omit")
        args.assert_called_once_with(4242)
        self.assertEqual(rec["kind"], "notify")
        self.assertEqual(rec["argv"], ["claude", "--name", "desk b", "--model", "opus[1m]", "--effort", "max",
                                       "--permission-mode", "auto", "--append-system-prompt", ""])
        self.assertEqual(rec["folder"], str(self.own_folder()))
        self.assertEqual(rec["tmux"], {"server": ["-L", "default"], "session": "work"})
        self.assertEqual(rec["env"], {"PATH": "/saved/bin:/usr/bin", "LANG": "C", "HANSA_CLAUDE": "/opt/claude",
                                      "XDG_STATE_HOME": str(self.tmp / "state")})
        self.assertEqual(rec["session"], self.SESS)
        from hansa import up
        self.assertEqual(rec["hansa"], up.hansa_command())
        text = (self.desk.state_dir / "coordinator-start.json").read_text()
        for secret in ("caller-key", self.IDENTITY, "u-1", "abc", "x.sock"):
            self.assertNotIn(secret, text)
        lines = said.splitlines()
        self.assertEqual(lines[0], "hansa now posts to this session")
        self.assertEqual(lines[1], f"After a restart, hansa up starts this session again in {self.own_folder()} with "
                         + shlex.join([*rec["argv"], "--continue"]) + ".")

    def test_notify_on_records_nothing_for_a_key_the_identity_or_what_it_cannot_read(self):
        (self.desk.secrets_dir / "provider.key").write_text(self.KEY)
        os.environ["CLAUDE_CODE_SESSION_ID"] = self.IDENTITY
        cases = {"one of the desk's keys": (["claude", "--append-system-prompt", "use " + self.KEY], None),
                 "the session's identity": (["claude", "--settings", '{"id": "%s"}' % self.IDENTITY], None),
                 "arguments of its claude process cannot be read": (None, None),
                 "folder of its claude process cannot be read": (["claude"], "")}
        for why, (argv, folder) in cases.items():
            with self.subTest(why=why):
                said, rec, _ = self.notify_on(argv, folder)
                self.assertIn("hansa up will not start this session again after a restart", said)
                self.assertIn(why, said)
                self.assertIn("nothing was recorded", said)
                self.assertEqual(rec["kind"], "unrecorded")  # no older command is started instead
                self.assertIn(why, rec["why"])
                self.assertEqual(set(rec), {"kind", "why", "session", "at"})
                self.assertNotIn(self.KEY, (self.desk.state_dir / "coordinator-start.json").read_text())
        # a session already recorded keeps its record when it cannot be read now
        self.notify_on(["claude", "--name", "n"])
        said, rec, _ = self.notify_on(None)
        self.assertEqual(rec["argv"], ["claude", "--name", "n"])
        self.assertIn("nothing new was recorded", said)
        self.assertIn("After a restart, hansa up starts this session again", said)
        # a session hansa coordinator started keeps that record: notify on reads nothing
        from hansa import up
        write_json(self.desk.state_dir / "coordinator-start.json",
                   {"kind": "coordinator", "words": ["--model", "opus"], "session": self.SESS})
        said, rec, args = self.notify_on(["claude", "--other"], HANSA_ROLE="coordinator")
        args.assert_not_called()
        self.assertEqual(rec["kind"], "coordinator")
        self.assertIn(shlex.join([up.hansa_command(), "--desk", str(self.desk.root), "coordinator", "--model", "opus",
                                  "--continue"]), said)

    def test_notify_on_decides_by_the_record_not_by_hansa_role(self):
        """A desk owner's wrapper sets HANSA_ROLE=coordinator on every hansa command it runs."""
        from hansa import up
        # no record of hansa coordinator for this session: recorded as any session is
        said, rec, args = self.notify_on(["claude", "--name", "desk b"], HANSA_ROLE="coordinator")
        args.assert_called_once_with(4242)
        self.assertEqual((rec["kind"], rec["argv"], rec["session"]), ("notify", ["claude", "--name", "desk b"],
                                                                       self.SESS))
        self.assertIn("After a restart, hansa up starts this session again", said)
        # hansa coordinator's record of another session (another pid, or the same pid started later) is replaced
        for other in ({"pid": 1, "start": "boot:77"}, {"pid": 4242, "start": "boot:78"}):
            with self.subTest(other=other):
                write_json(self.desk.state_dir / "coordinator-start.json",
                           {"kind": "coordinator", "words": ["--model", "opus"], "session": other})
                _, rec, args = self.notify_on(["claude", "--name", "desk b"], HANSA_ROLE="coordinator")
                args.assert_called_once_with(4242)
                self.assertEqual((rec["kind"], rec["session"]), ("notify", self.SESS))
        # the session hansa coordinator started keeps that record and is not recorded again as notify
        write_json(self.desk.state_dir / "coordinator-start.json",
                   {"kind": "coordinator", "words": ["--model", "opus"], "session": self.SESS})
        said, rec, args = self.notify_on(["claude", "--other"], HANSA_ROLE="coordinator")
        args.assert_not_called()
        self.assertEqual((rec["kind"], rec["words"], rec["session"]), ("coordinator", ["--model", "opus"], self.SESS))
        self.assertIn(shlex.join([up.hansa_command(), "--desk", str(self.desk.root), "coordinator", "--model", "opus",
                                  "--continue"]), said)

    def desk_at(self, root):
        """This test's desk at root (the session's folder made around or beside it)."""
        self.desk = Desk(root)
        for d in (self.desk.root, self.desk.tasks_dir, self.desk.secrets_dir, self.desk.state_dir):
            d.mkdir(parents=True, exist_ok=True)
        write_json(self.desk.settings_path, {})
        return self.desk

    def status_line(self):
        return next(x for x in views.status_text(views.status(self.desk)).splitlines() if x.startswith("hansa posts"))

    def copy_of(self, folder):
        return Path(folder) / ".claude" / "rules" / "hansa-card.md"

    def test_notify_on_copies_the_card_into_a_session_beside_the_desk(self):
        project = self.tmp / "project"
        project.mkdir()
        desk = cli.init_desk(self.tmp / "desk", "", "a", "")
        self.desk = desk
        card = (desk.root / "CLAUDE.md").read_text()
        said, rec, _ = self.notify_on(["claude"], str(project), HANSA_ROLE="coordinator")
        self.assertEqual(rec["kind"], "notify")
        copy = self.copy_of(project)
        text = copy.read_text()
        header, body = text.split("\n\n", 1)
        self.assertTrue(header.startswith(f"<!-- hansa: copy of the coordinator's card for the desk at {desk.root} "))
        for words in ("hansa notify off", "edits to it are lost", "not started by `hansa coordinator`",
                      "scout, reviewer, operator", "the coordinator's mod", "make a task"):
            self.assertIn(words, header)
        self.assertTrue(header.endswith(
            "\n>\n> This card is for the session that coordinates that desk: the one hansa posts its notices to. "
            "Any other session started in this folder or below it, such as a worker a script starts or a session "
            "for other work, is not that session: ignore this card."))
        self.assertIn("## Never", body)
        # the card's import of the project's rules names a file outside this folder: a pointer to it, no import
        self.assertNotIn("\n@notes/PROJECT.md\n", body)
        self.assertIn(str(Path(os.path.realpath(desk.project_path))), body)
        self.assertEqual(body.count("\n"), card.count("\n"))
        for words in (str(copy), f"every Claude Code session started in {project}, or in a folder below it",
                      "at each start", "hansa's own runs leave it out", "reads it from its next start",
                      "hansa help card"):
            self.assertIn(words, said)
        self.assertNotIn("Add this line", said)
        self.assertNotIn("Allow external", said)  # a plain file inside the folder, no import
        self.assertNotIn("git", said.split("notify off.", 1)[1])  # not a git work tree
        self.assertIn(f"reads the card from {copy}", self.status_line())
        self.assertIn(f"reads the coordinator's card from {copy}", views.explain_text(desk, "notify"))

    def test_a_session_started_by_hand_is_told_it_lacks_the_coordinators_rules_until_hansa_up_starts_it(self):
        """The principal starts Claude Code by hand in a folder of their own, then runs hansa notify on in it."""
        project = self.own_folder()
        self.desk = cli.init_desk(self.tmp / "desk", "", "a", "")
        said, rec, _ = self.notify_on(["claude", "--name", "n"], str(project))
        self.assertNotIn("launch_rules", rec)
        [line] = [x for x in said.splitlines() if "deny rules" in x]
        for words in ("none of the deny rules hansa coordinator gives its own session", "no pushing or publishing",
                      "secrets/ and .hansa/", "until hansa up starts it again", "principal's list",
                      "lanes' repositories", "no helpers"):
            self.assertIn(words, line)
        self.assertIn("files but notes/ and worktrees/)", line)
        header = self.copy_of(project).read_text().split("\n\n", 1)[0]
        self.assertIn("no editing of the desk's files but `notes/` and `worktrees/`.", header)
        for words in ("> Started by `hansa up`, it has these of the rules `hansa coordinator` gives its session: no "
                      "pushing or publishing from its shell, no reading of the desk's `secrets/` and `.hansa/`",
                      "Started otherwise and recorded with `hansa notify on`, it has none of them until `hansa up` "
                      "starts it.", "In both cases it is not denied Read on the principal's list of what workers may "
                      "not read, nor Edit in the lanes' repositories", "scout, reviewer, operator"):
            self.assertIn(words, header)
        # the session hansa coordinator started is not told so
        write_json(self.desk.state_dir / "coordinator-start.json",
                   {"kind": "coordinator", "words": [], "folder": str(self.desk.root), "session": self.SESS})
        said, _, _ = self.notify_on(["claude"], str(project))
        self.assertNotIn("deny rules", said)

    def test_a_session_started_by_hand_in_the_desk_is_told_the_rules_it_has_from_the_desks_settings(self):
        self.desk = cli.init_desk(self.tmp / "desk", "", "a", "")
        inside = self.desk.root / "notes"
        for folder in (*cli.desk_spellings(self.desk), str(inside)):  # each spelling of the desk's folder
            with self.subTest(folder=folder):
                said, rec, _ = self.notify_on(["claude", "--name", "n"], folder)
                self.assertEqual(rec["folder"], folder)
                [line] = [x for x in said.splitlines() if "deny rules" in x]
                if folder == str(inside):  # not the desk's own folder: today's line
                    self.assertIn("none of the deny rules", line)
                    continue
                self.assertNotIn("none of the deny rules", line)
                for words in ("from the desk's .claude/settings.json", "no pushing or publishing",
                              "no reading of the desk's secrets/ and .hansa/", "no editing of the desk's "
                              "settings.json, secrets/, tasks/, .hansa/, events.jsonl and lanes/", "The rest",
                              "logins and keys", "but notes/ and worktrees/", "come when hansa up starts it"):
                    self.assertIn(words, line)

    def test_notify_no_card_persists_until_card_is_enabled(self):
        from hansa import up
        project = self.own_folder()
        self.desk = desk = cli.init_desk(self.tmp / "desk", "", "a", "")
        said, rec, _ = self.notify_on(["claude"], str(project), flags=["--no-card"])
        self.assertEqual((rec["kind"], rec["folder"], rec["session"]), ("notify", str(project), self.SESS))
        self.assertFalse(self.copy_of(project).exists())
        for text in (said, self.say("status"), self.say("explain", "notify")):
            self.assertIn("does not read", text)
            self.assertIn("copy is turned off", text)
            self.assertIn("hansa notify on --card", text)
            self.assertNotIn("@", text)
        # A different session rewrites its start record, but keeps the desk's choice.
        _, rec, _ = self.notify_on(["claude", "--name", "new"], str(project),
                                   sess={"pid": 4343, "start": "boot:88"})
        self.assertEqual(rec["argv"], ["claude", "--name", "new"])
        self.assertFalse(self.copy_of(project).exists())
        self.serve_until_web(desk)
        self.assertFalse(self.copy_of(project).exists())
        with unittest.mock.patch.object(notify, "turn_off", return_value="hansa no longer posts to this session"):
            self.say("notify", "off")
        self.notify_on(["claude"], str(project))
        self.assertFalse(self.copy_of(project).exists())
        said, _, _ = self.notify_on(["claude"], str(project), flags=["--card"])
        self.assertTrue(self.copy_of(project).read_text().startswith(up.COPY_MARK))
        self.assertIn("wrote a copy", said)
        self.assertNotIn("copy is turned off", self.say("status"))

    def test_notify_no_card_removes_only_hansas_copies(self):
        project = self.own_folder()
        self.desk = cli.init_desk(self.tmp / "desk", "", "a", "")
        self.notify_on(["claude"], str(project))
        self.assertTrue(self.copy_of(project).is_file())
        said, _, _ = self.notify_on(["claude"], str(project), flags=["--no-card"])
        self.assertFalse(self.copy_of(project).exists())
        self.assertIn("hansa removed its earlier copy of the card,", said)
        self.assertIn(str(self.copy_of(project)), said)
        self.notify_on(["claude"], str(project))
        self.assertFalse(self.copy_of(project).exists())
        self.notify_on(["claude"], str(project), flags=["--card"])
        self.copy_of(project).write_text("my own rules\n")
        self.notify_on(["claude"], str(project), flags=["--no-card"])
        self.assertEqual(self.copy_of(project).read_text(), "my own rules\n")

    def test_card_refresh_does_not_rewrite_a_copy_while_off(self):
        from hansa import up
        project = self.own_folder()
        self.desk = desk = cli.init_desk(self.tmp / "desk", "", "a", "")
        _, rec, _ = self.notify_on(["claude"], str(project))
        before = up.card_check(desk, rec)
        copy = self.copy_of(project)
        stale = copy.read_text().split("\n\n", 1)[0] + "\n\nan older copy\n"
        self.notify_on(["claude"], str(project), flags=["--no-card"])
        # An old file put back after opting out must not be refreshed by either start.
        copy.write_text(stale)
        up.write_copy(desk, before)  # even a state read before opting out cannot write
        self.assertEqual(copy.read_text(), stale)
        self.serve_until_web(desk)
        self.assertEqual(copy.read_text(), stale)
        cli.coordinator_desk(desk, os.getuid())
        self.assertEqual(copy.read_text(), stale)

    def test_notify_card_flags_require_on(self):
        for words in (("off", "--no-card"), ("--card",)):
            with self.subTest(words=words), self.assertRaisesRegex(SystemExit, "notify on"):
                self.say("notify", *words)

    def test_the_copy_is_kept_out_of_the_git_repository_of_a_session_that_holds_the_desk(self):
        project = self.tmp / "project"
        project.mkdir()
        sh("git", "init", "-q", str(project), cwd=self.tmp)
        (project / "README").write_text("mine\n")
        self.desk = desk = cli.init_desk(project / "desk", "", "a", "")
        before = subprocess.run(["git", "status", "--porcelain"], cwd=project, capture_output=True, text=True).stdout
        exclude = project / ".git" / "info" / "exclude"
        said, _, _ = self.notify_on(["claude"], str(project), HANSA_ROLE="coordinator")
        copy = self.copy_of(project)
        self.assertTrue(copy.is_file())
        self.assertIn("\n@../../desk/notes/PROJECT.md\n", copy.read_text())  # read from the copy's folder
        self.assertEqual(exclude.read_text().splitlines().count("/.claude/rules/hansa-card.md"), 1)
        self.assertIn(f"added it to {os.path.realpath(exclude)}", said)
        self.assertEqual(subprocess.run(["git", "status", "--porcelain"], cwd=project, capture_output=True,
                                        text=True).stdout, before)
        said, _, _ = self.notify_on(["claude"], str(project), HANSA_ROLE="coordinator")
        self.assertEqual(exclude.read_text().splitlines().count("/.claude/rules/hansa-card.md"), 1)
        self.assertNotIn("added it", said)
        self.assertIn("ignores it", said)
        # a path git ignores by itself: nothing added
        exclude.write_text("")
        (project / ".gitignore").write_text(".claude/\n")
        said, _, _ = self.notify_on(["claude"], str(project), HANSA_ROLE="coordinator")
        self.assertEqual(exclude.read_text(), "")
        # a tracked file there is never changed, even one with hansa's header
        (project / ".gitignore").unlink()
        sh("git", "add", "-f", ".claude/rules/hansa-card.md", cwd=project)
        copy.write_text(copy.read_text() + "committed\n")
        said, _, _ = self.notify_on(["claude"], str(project), HANSA_ROLE="coordinator")
        self.assertTrue(copy.read_text().endswith("committed\n"))
        self.assertIn("git tracks", said)
        self.assertIn("Add this line", said)

    def test_rewriting_the_desks_card_rewrites_its_copy(self):
        project = self.tmp / "project"
        project.mkdir()
        self.desk = desk = cli.init_desk(self.tmp / "desk", "", "a", "")
        self.notify_on(["claude"], str(project), HANSA_ROLE="coordinator")
        copy = self.copy_of(project)
        mine = copy.read_text()
        # the copy is made from hansa's own card, never from the desk's CLAUDE.md as it stands
        (desk.root / "CLAUDE.md").write_text("an older card\n")
        copy.write_text(mine.split("\n\n", 1)[0] + "\n\nan older copy\n")
        self.notify_on(["claude"], str(project), HANSA_ROLE="coordinator")  # every notify on writes it again
        self.assertEqual(copy.read_text(), mine)
        self.assertNotIn("an older card", mine)
        copy.write_text(mine.split("\n\n", 1)[0] + "\n\nan older copy\n")
        cli.coordinator_desk(desk, os.getuid())  # hansa coordinator's start refreshes the card, and so the copy
        self.assertEqual((desk.root / "CLAUDE.md").read_text(), cli.CARD.read_text())
        self.assertEqual(copy.read_text(), mine)
        self.assertIn("## Never", copy.read_text())
        # a copy in a folder that holds the desk would reach the session hansa coordinator starts there: removed
        inner = self.tmp / "inner"
        inner.mkdir()
        self.desk = desk = cli.init_desk(inner / "desk", "", "a", "")
        self.notify_on(["claude"], str(inner), HANSA_ROLE="coordinator")
        self.assertTrue(self.copy_of(inner).is_file())
        cli.coordinator_desk(desk, os.getuid())
        self.assertFalse(self.copy_of(inner).exists())

    def serve_until_web(self, desk):
        """hansa serve's start up to its web server, which this test does not start; its lock let go after."""
        with cli.hold_server_lock(desk) as held, \
                unittest.mock.patch.object(cli, "hold_server_lock", return_value=held), \
                unittest.mock.patch("hansa.web.start_web", side_effect=RuntimeError("no page in this test")), \
                self.assertRaisesRegex(RuntimeError, "no page"):
            main(["--desk", str(desk.root), "serve", "--port", "0"])

    def test_hansa_serve_brings_the_desks_card_and_its_copy_up_to_date(self):
        project = self.tmp / "project"
