    def orphan_starting(self, **fields):
        """A worker an earlier server started, and a task it left in `starting`: (task, worker)."""
        token = f"hansa-launch-test-{uuid.uuid4().hex[:8]}"  # another suite running meanwhile has its own
        claimed = time.time()  # as a server claims a task before it starts the worker
        orphan = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(60)", token], start_new_session=True)
        self.addCleanup(lambda: orphan.poll() is None and (orphan.kill(), orphan.wait()))
        tid = self.desk.new_task("Add hello.txt")
        self.desk.update(tid, state="running", phase="starting", lane="a", provider="claude", started=claimed,
                         pid=None, launch=token, **fields)
        return tid, orphan

    def test_an_idle_round_reads_the_tasks_once_and_the_releases_once_for_each_of_their_rounds(self):
        from hansa import release
        for i in range(3):  # a desk with a history, and nothing to do
            self.desk.update(self.desk.new_task(f"Task {i}", lane="a"), state="merged", merged=time.time())
        release._write(self.desk, [{"id": 1, "lane": "a", "state": "done", "repo": str(self.repo)}])
        d = Dispatcher(self.desk)
        d.tick()  # the first round also does what a server does once
        with unittest.mock.patch.object(self.desk, "tasks", wraps=self.desk.tasks) as tasks, \
                unittest.mock.patch.object(release, "releases", wraps=release.releases) as releases:
            d.tick()
            self.assertEqual(tasks.call_count, 1)  # not once for each thing the round looks at
            self.assertEqual(releases.call_count, 2)  # the releases' round (release.tick), and the merge checks'
            # a task added by another process is seen in the next round; one this round changes, in the rest of it
            tid = self.desk.new_task("Add hello.txt", lane="a")
            d.tick()
            self.assertEqual(self.desk.meta(tid)["state"], "running")
            self.assertEqual(tasks.call_count, 2)
            self.assertEqual([m["state"] for m in d.tasks() if m["id"] == tid], ["running"])
            self.assertEqual(tasks.call_count, 3)
        self.assertEqual(self.settle(d, tid)["state"], "done")

    def test_a_worker_started_just_before_the_server_stopped_is_taken_over(self):
        tid, orphan = self.orphan_starting()
        Dispatcher(self.desk).tick()
        m = self.desk.meta(tid)
        self.assertEqual((m["state"], m["phase"], m["pid"]), ("running", "", orphan.pid), m)
        self.assertIsNone(orphan.poll())  # still working, not stopped and started over

    def test_a_test_leaves_neither_its_folder_nor_its_environment(self):
        before = dict(os.environ)
        case = DeskTest("test_a_task_that_ends_after_its_check_is_posted_once_to_its_session")  # a worker, a follower
        result = unittest.TestResult()
        case.run(result)
        self.assertEqual((result.testsRun, result.errors, result.failures), (1, [], []))
        self.assertNotEqual(case.tmp, self.tmp)
        self.assertFalse(case.tmp.exists())
        time.sleep(1.5)  # a follower ends a moment after its session: none is left to write there again
        self.assertFalse(case.tmp.exists())
        self.assertEqual(dict(os.environ), before)

    def test_a_worker_is_taken_over_every_time_while_processes_start_and_end_around_it(self):
        stop = threading.Event()

        def churn():  # short-lived processes, as on a busy machine
            while not stop.is_set():
                subprocess.run(["/bin/sleep", "0.01"])
        churners = [threading.Thread(target=churn, daemon=True) for _ in range(3)]
        for t in churners:
            t.start()
        self.addCleanup(lambda: (stop.set(), [t.join() for t in churners]))
        for i in range(20):
            tid, orphan = self.orphan_starting()
            Dispatcher(self.desk).tick()
            m = self.desk.meta(tid)
            self.assertEqual((m["state"], m["phase"], m["pid"]), ("running", "", orphan.pid), (i, m))
            self.assertIsNone(orphan.poll())
            orphan.kill()
            orphan.wait()
            self.desk.update(tid, state="failed", phase="", pid=None)  # out of the way of the next one

    def test_while_the_process_list_cannot_be_read_a_starting_task_is_left_as_it_is(self):
        from hansa import run
        tid, orphan = self.orphan_starting()
        d = Dispatcher(self.desk)
        with unittest.mock.patch.object(run, "pids_with_arg", side_effect=run.CannotLook("the process list could not be read")):
            d.tick()
            d.tick()
        m = self.desk.meta(tid)
        self.assertEqual((m["state"], m["phase"], m["pid"]), ("running", "starting", None), m)  # not queued, not started
        self.assertTrue(m["lookup_failing_since"])
        self.assertFalse(self.desk.raw_dir(tid).joinpath("run.json").exists())  # no second worker
        failed = [e for e in map(json.loads, self.desk.events_path.read_text().splitlines())
                  if e["event"] == "process_lookup_failed"]
        self.assertEqual([(e["task"], e["looking_for"]) for e in failed], [(tid, "worker")] * 2)
        d.tick()  # the list reads again
        m = self.desk.meta(tid)
        self.assertEqual((m["state"], m["phase"], m["pid"], m["lookup_failing_since"]), ("running", "", orphan.pid, None), m)
        self.assertIsNone(orphan.poll())

    def test_a_task_hansa_cannot_look_for_for_minutes_fails_and_is_not_started_again(self):
        from hansa import run
        tid, orphan = self.orphan_starting(lookup_failing_since=time.time() - run.LOOK_LIMIT - 1)
        with unittest.mock.patch.object(run, "pids_with_arg", side_effect=run.CannotLook("the process list could not be read")):
            Dispatcher(self.desk).tick()
        m = self.desk.meta(tid)
        self.assertEqual((m["state"], m["phase"], m["pid"]), ("failed", "", None), m)
        self.assertIn("could not read the process list for 5 minutes", m["error"])
        self.assertFalse(self.desk.raw_dir(tid).joinpath("run.json").exists())

    def test_a_process_whose_arguments_cannot_be_read_is_not_taken_for_gone(self):
        from hansa import run
        if not run._ON_MAC:
            self.skipTest("Linux reads /proc")
        tid, orphan = self.orphan_starting()
        real = run._mac_procargs
        with unittest.mock.patch.object(run, "_mac_procargs", side_effect=lambda p: None if p == orphan.pid else real(p)), \
                unittest.mock.patch.object(run.time, "sleep"), self.assertRaises(run.CannotLook):
            run.pids_with_arg(self.desk.meta(tid)["launch"])
        self.assertEqual(run.pids_with_arg(self.desk.meta(tid)["launch"]), [orphan.pid])

    def test_a_process_read_half_way_through_an_exec_is_read_again(self):
        from hansa import run
        if not run._ON_MAC:
            self.skipTest("Linux reads /proc")
        tid, orphan = self.orphan_starting()
        real, halves = run._mac_procargs, [([b"ython3", b"", b""], [], False), ([b""], [], False)]  # as mid-exec
        with unittest.mock.patch.object(run, "_mac_procargs",
                                        side_effect=lambda p: halves.pop(0) if p == orphan.pid and halves else real(p)), \
                unittest.mock.patch.object(run.time, "sleep"):
            self.assertEqual(run.pids_with_arg(self.desk.meta(tid)["launch"]), [orphan.pid])

    def test_a_process_never_read_whole_is_not_the_worker_and_does_not_stop_the_lookup(self):
        from hansa import run
        if not run._ON_MAC:
            self.skipTest("Linux reads /proc")
        tid, orphan = self.orphan_starting()
        other = subprocess.Popen(["/bin/sleep", "60"], start_new_session=True)
        self.addCleanup(lambda: other.poll() is None and (other.kill(), other.wait()))
        real, reads = run._mac_procargs, {orphan.pid: 0, other.pid: 0}

        def procargs(p):  # the worker half written once; the other half written, and differently, every time
            if p not in reads:
                return real(p)
            reads[p] += 1
            if p == other.pid:
                return [b"x" * reads[p]], [], False
            return ([b"ython3", b"", b""], [], False) if reads[p] == 1 else real(p)
        with unittest.mock.patch.object(run, "_mac_procargs", side_effect=procargs), \
                unittest.mock.patch.object(run.time, "sleep"):
            self.assertEqual(run.pids_with_arg(self.desk.meta(tid)["launch"], self.desk.meta(tid)["started"]),
                             [orphan.pid])
        self.assertEqual(reads[other.pid], 1 + run.LOOK_TRIES)

    def test_a_process_read_alike_twice_is_taken_as_it_reads_after_the_second_read(self):
        from hansa import run
        if not run._ON_MAC:
            self.skipTest("Linux reads /proc")
        tid, orphan = self.orphan_starting()
        # an empty first argument reads as half written every time
        other = subprocess.Popen(["perl", "-e", 'exec {"/bin/sleep"} "", 60'], start_new_session=True)
        self.addCleanup(lambda: other.poll() is None and (other.kill(), other.wait()))
        end = time.time() + 10
        while (run._mac_procargs(other.pid) or [[b"perl"]])[0][:1] != [b"60"] and time.time() < end:
            time.sleep(0.02)
        real, reads = run._mac_procargs, []
        with unittest.mock.patch.object(run, "_mac_procargs", side_effect=lambda p: (reads.append(p), real(p))[1]):
            m = self.desk.meta(tid)
            self.assertEqual(run.pids_with_arg(m["launch"], m["started"]), [orphan.pid])
        self.assertEqual(reads.count(other.pid), 2)

    def test_whole_arguments_are_told_from_half_written_ones(self):
        from hansa import run
        if not run._ON_MAC:
            self.skipTest("Linux reads /proc")
        tid, orphan = self.orphan_starting()
        end = time.time() + 10
        while orphan.pid not in run.pids_with_arg(self.desk.meta(tid)["launch"]) and time.time() < end:
            time.sleep(0.05)
        data = run._sysctl(run._CTL_KERN, run._KERN_PROCARGS2, orphan.pid)
        argv, _, whole = run._mac_parse_args(data)  # the first argument is the Python the executable ran
        self.assertEqual((argv[1:], whole), ([b"-c", b"import time; time.sleep(60)", self.desk.meta(tid)["launch"].encode()],
                                             True))
        path = b"/Applications/Xcode.app/Contents/Developer/usr/bin/python3"  # 58 bytes: 6 NULs to 64
        argv = [path, b"-c", b"import time; time.sleep(3)", b"tok"]
        read = struct.pack("@i", 4) + path + b"\0" * 6 + b"\0".join(argv + [b"HOME=/h", b"", b""]) + b"\0" * 40
        self.assertEqual(run._mac_parse_args(read), (argv, [b"HOME=/h"], True))
        # a process that rewrote its own arguments, as postgres does: whole
        title = struct.pack("@i", 3) + b"/opt/pg/bin/postgres" + b"\0" * 4 + b"postgres: walwriter " + b"\0" * 40
        self.assertEqual(run._mac_parse_args(title), ([b"postgres: walwriter ", b"", b""], [], True))
        # as macOS gave them in the middle of an exec: all NULs, and a NUL in the path
        self.assertFalse(run._mac_parse_args(struct.pack("@i", 4) + b"\0" * 200)[2])
        cut = read[:4 + 51] + b"\0" + read[4 + 52:]
        self.assertEqual(run._mac_parse_args(cut)[0], [b"ython3", b"", b"", b""])
        self.assertFalse(run._mac_parse_args(cut)[2])

    def test_a_process_that_keeps_execing_itself_does_not_stop_the_lookup(self):
        from hansa import run
        tid, orphan = self.orphan_starting()
        again = ("import os, sys, time; time.sleep(0.01); "
                 "os.execv(sys.executable, [sys.executable, '-c', sys.argv[1], sys.argv[1], str(int(sys.argv[2]) + 1)])")
        other = subprocess.Popen([sys.executable, "-c", again, again, "0"], start_new_session=True)
        self.addCleanup(lambda: other.poll() is None and (other.kill(), other.wait()))
        m, real, first = self.desk.meta(tid), run._mac_procargs, []

        def procargs(p):  # the worker is read half written the first time in each lookup, as mid-exec
            if p == orphan.pid and not first:
                first.append(p)
                return [b"ython3", b"", b""], [], False
            return real(p)
        with unittest.mock.patch.object(run, "_mac_procargs", side_effect=procargs):
            for _ in range(20):
                first.clear()
                self.assertEqual(run.pids_with_arg(m["launch"], m["started"]), [orphan.pid])
        self.assertIsNone(other.poll())

    def unreadable_beside(self, change):
        """On macOS: a worker left in `starting`, and beside it a process of this account that leads its
        own group and never lets its arguments be read, whose kinfo_proc record `change` alters as it is
        read: (launch word, claim time, worker)."""
        from hansa import run
        if not run._ON_MAC:
            self.skipTest("Linux reads /proc")
        other = subprocess.Popen(["/bin/sleep", "60"], start_new_session=True)
        self.addCleanup(lambda: other.poll() is None and (other.kill(), other.wait()))
        tid, orphan = self.orphan_starting()
        real_sysctl, real_args = run._sysctl, run._mac_procargs

        def sysctl(*mib, **kw):
            data = real_sysctl(*mib, **kw)
            if data and mib[1:3] == (run._KERN_PROC, run._KERN_PROC_ALL):
                size, recs = run._KINFO_PROC_SIZE, bytearray(data)
                for i in range(0, len(recs) - size + 1, size):
                    if struct.unpack_from("@i", recs, i + 40)[0] == other.pid:
                        change(recs, i)
                data = bytes(recs)
            return data
        patches = [unittest.mock.patch.object(run, "_sysctl", side_effect=sysctl),
                   unittest.mock.patch.object(run, "_mac_procargs", side_effect=lambda p: None if p == other.pid else real_args(p)),
                   unittest.mock.patch.object(run.time, "sleep")]
        for p in patches:
            p.start()
            self.addCleanup(p.stop)
        m = self.desk.meta(tid)
        return m["launch"], m["started"], orphan

    def test_an_unreadable_process_older_than_the_claim_does_not_stop_the_lookup(self):
        from hansa import run
        token, claimed, orphan = self.unreadable_beside(lambda recs, i: struct.pack_into("@l", recs, i, int(claimed) - 60))
        with self.assertRaises(run.CannotLook):  # were it as new as the claim, it might be the worker
            run.pids_with_arg(token)
        self.assertEqual(run.pids_with_arg(token, claimed), [orphan.pid])

    def test_an_unreadable_setuid_process_does_not_stop_the_lookup(self):
        from hansa import run
        token, claimed, orphan = self.unreadable_beside(lambda recs, i: struct.pack_into("@I", recs, i + 420, 0))
        self.assertEqual(run.pids_with_arg(token, claimed), [orphan.pid])  # root as its effective user: sudo, say

    def test_an_unreadable_process_as_new_as_the_claim_still_stops_the_lookup(self):
        from hansa import run
        token, claimed, orphan = self.unreadable_beside(lambda recs, i: None)
        with self.assertRaises(run.CannotLook):
            run.pids_with_arg(token, claimed)

    def test_a_check_an_earlier_server_finished_is_not_run_again(self):
        marker = self.tmp / "checked"
        s = self.desk.settings()
        s["lanes"]["a"]["check"] = f"touch {marker}"
        self.assertEqual(self.desk.save_settings(s), [])
        tid = self.desk.new_task("Add hello.txt")
        self.desk.update(tid, state="running", phase="checking", lane="a", provider="claude", started=time.time(),
                         pid=None, launch="hansa-check-t0001-gone", worktree=str(self.repo), check_command=f"touch {marker}")
        raw = self.desk.raw_dir(tid)
        (raw / "check.exit").write_text("0\n")
        (raw / "check.log").write_text("all passed\n")
        m = self.settle(Dispatcher(self.desk), tid)
        self.assertEqual((m["state"], m["check"]["ok"], m["check"]["tail"]), ("done", True, ["all passed"]), m)
        self.assertFalse(marker.exists())

    # Start-record failures (ENOSPC, both one failed write and no writes until space returns):
    # | kind                    | its start record fails                         |
    # | worker                  | stopped group; failed; no second start         |
    # | verification worker     | stopped group; failed; no second start         |
    # | lane check              | stopped group; failed; no second start         |
    # | merge check             | stopped group; done/back for review; no restart|
    # | try                     | stopped group; done/ok=False; no second start  |
    # | release (shared/fixed)   | stopped group; failed; no second start         |
    # | recovered worker/verify | stopped group; failed; no second start         |
    # | recovered lane check    | stopped group; failed; no second start         |
    # | recovered merge check   | stopped group; done/back for review; no restart|
    # | recovered release       | stopped group; failed; no second start         |
    # | resumed worker/verify   | stopped group; original run ends; no new resume|
    # Restart before the failure can be saved (new launches and failed recovery writes):
    # | kind                | unrecorded start after restart                     |
    # | worker/verification | queued, then dispatched; old group gone first      |
    # | lane check          | check runs again; old group gone first             |
    # | merge check         | check runs again; old group gone first             |
    # | try                 | done/ok=False; no second start                     |
    # | release shared/fixed| failed/lost; no second start                       |
    # There is no durable failed-start marker: a fresh Desk uses ordinary recovery.

    def start_record_group(self, token, marker, popen):
        """A real leader and independent child: neither ends by itself or waits for the other."""
        child = ("import os, pathlib, sys, time\n"
                 "pathlib.Path(sys.argv[1]).write_text(str(os.getpid()))\n"
                 "while True: time.sleep(3600)\n")
        code = ("import subprocess, sys, time\n"
                f"subprocess.Popen([sys.executable, '-c', {child!r}, sys.argv[1]])\n"
                "while True: time.sleep(3600)\n")
        proc = popen([sys.executable, "-c", code, str(marker), token], start_new_session=True)

        def cleanup():
            # Independent of the cleanup under test, including a missing stop or leader-only stop.
            from hansa import run
            if run.group_running(proc.pid):
                os.killpg(proc.pid, signal.SIGKILL)
            proc.wait(timeout=10)
            end = time.time() + 3
            while run.group_running(proc.pid) and time.time() < end:
                time.sleep(0.01)
            self.assertFalse(run.group_running(proc.pid), "fixture cleanup left its child running")
        self.addCleanup(cleanup)
        end = time.time() + 10
        while time.time() < end:
            try:
                proc.child_pid = int(marker.read_text())
                return proc
            except (FileNotFoundError, ValueError):
                time.sleep(0.01)
        self.fail("process fixture did not record its child's pid")

    def test_start_record_group_waits_for_the_child_pid_to_be_written(self):
        marker = self.tmp / "delayed-child.pid"
        popen = subprocess.Popen

        def delayed_writer(argv, **kwargs):
            argv[2] = argv[2].replace(".write_text(str(os.getpid()))",
                                    ".touch(); time.sleep(0.2); pathlib.Path(sys.argv[1]).write_text(str(os.getpid()))")
            return popen(argv, **kwargs)

        proc = self.start_record_group("delayed-marker", marker, delayed_writer)
        self.assertGreater(proc.child_pid, 0)
        self.assertEqual(proc.child_pid, int(marker.read_text()))

    def assert_start_record_group_stopped(self, proc):
        from hansa import run
        self.assertIsNotNone(proc.poll(), "pid record failed but its process is still running")
        self.assertFalse(run.group_running(proc.pid), "pid record failed but its group is still running")
        self.assertTrue(not run.alive(proc.child_pid) or run._state(proc.child_pid) == "Z",
                        "the process's child is still running")

    def test_a_failed_pid_record_does_not_add_an_unbounded_wait_after_stop(self):
        from hansa import run
        for recovered in (False, True):
            with self.subTest(recovered=recovered):
                proc = self.start_record_group("bounded-start-record", self.tmp / f"bounded-{recovered}.pid",
                                               subprocess.Popen)
                waitpid, wait = os.waitpid, proc.wait

                def reap(pid, options):
                    self.assertNotEqual(options, 0, "unbounded wait after stopping a recovered group")
                    return waitpid(pid, options)

                def bounded_wait(timeout=None):
                    self.assertIsNotNone(timeout, "unbounded wait after stopping a child group")
                    return wait(timeout=timeout)

                def overdue(*args):
                    self.fail("stopping the fixture's group did not finish within three seconds")
                handler = signal.signal(signal.SIGALRM, overdue)
                signal.setitimer(signal.ITIMER_REAL, 3)
                try:
                    with unittest.mock.patch.object(os, "waitpid", side_effect=reap), \
                            unittest.mock.patch.object(proc, "wait", side_effect=bounded_wait):
                        with self.assertRaisesRegex(OSError, "start record disk full"):
                            with run.recording_start(self.desk, None, proc.pid, None if recovered else proc):
                                raise OSError(errno.ENOSPC, "start record disk full")
                finally:
                    signal.setitimer(signal.ITIMER_REAL, 0)
                    signal.signal(signal.SIGALRM, handler)
                self.assert_start_record_group_stopped(proc)

    def unrecordable_start(self, kind, recovering, persistent, restart=False):
        from hansa import release, run
        # Each table cell has its own repository and desk, including when a base failure leaves a claim.
        folder = self.tmp / f"start-{kind.replace(' ', '-')}-{recovering}-{persistent}-{restart}"
        folder.mkdir()
        repo = folder / "repo"
        sh("git", "clone", "-q", str(self.repo), str(repo), cwd=folder)
        self.desk = init_desk(folder / "desk", str(repo), "a")
        s = self.desk.settings()
        s["lanes"]["a"].update(check="sleep 60", merge_check="sleep 60", release="sleep 60")
        if kind == "release fixed":
            s["lanes"]["a"]["release"] = ""
            s["lanes"]["a"]["targets"] = {"cut": {"command": "sleep 60", "fixed": True}}
        self.assertEqual(self.desk.save_settings(s), [])
        d, tid, rid = Dispatcher(self.desk), None, None
        token = f"hansa-start-record-{uuid.uuid4().hex}"
        if kind.startswith("release"):
            r = release.ask(self.desk, "a", target="cut" if kind == "release fixed" else None)
            rid = r["id"]
            self.assertEqual(release.answer(self.desk, rid, True, commit=r["commit"], command=r["command"]), {"ok": True})
            if recovering:
                release.change(self.desk, rid, lambda x: {"state": "starting", "launch": token, "started": now()})
        elif kind == "try":
            run.write_try(self.desk, "a", {"phase": "queued"})
        else:
            tid = self.desk.new_task("A start-record fixture", lane="a", kind="verify" if kind == "verification" else "work")
            if kind == "merge check":
                head = sh_out("git", "rev-parse", "HEAD", cwd=repo)
                sh("git", "branch", f"task/{tid}", head, cwd=repo)
                self.desk.update(tid, state="merging", provider="claude", head=head, branch=f"task/{tid}",
                                 merge_check={"phase": "starting" if recovering else "queued", "launch": token,
                                              "started": now()})
            elif kind == "check" or recovering:
                wt = run.prepare(self.desk, "a", s["lanes"]["a"], self.desk.meta(tid))[0] if kind == "check" else repo
                self.desk.update(tid, state="running", phase="checking" if kind == "check" else "starting",
                                 provider="claude", pid=None, launch=token, started=now(), check_started=now(),
                                 check_command="sleep 60", worktree=str(wt))
        marker, procs = folder / "child.pid", []
        popen, write = subprocess.Popen, write_json
        if recovering:
            procs.append(self.start_record_group(token, marker, popen))
        launches = []

        def launch(argv, **kwargs):
            if not kwargs.get("start_new_session"):
                return popen(argv, **kwargs)
            for previous in procs:
                self.assert_start_record_group_stopped(previous)
            launches.append(argv)
            if tid:
                m = self.desk.meta(tid)
                word = (m.get("merge_check") or {}).get("launch") if kind == "merge check" else m.get("launch")
            else:
                word = release.get(self.desk, rid).get("launch") if rid else run.read_try(self.desk, "a").get("launch")
            p = self.start_record_group(word, folder / f"child-{len(procs)}.pid", popen)
            procs.append(p)
            return p
        full = []

        def save(path, data):
            rows = data if isinstance(data, list) else [data]
            records_pid = procs and any(isinstance(x, dict) and
                                       (x.get("pid") == procs[0].pid or
                                        (x.get("merge_check") or {}).get("pid") == procs[0].pid) for x in rows)
            if records_pid or (persistent and full):
                full.append(str(path))
                raise OSError(errno.ENOSPC, "start record disk full")
            return write(path, data)

        def tick():
            try:
                d.tick()
            except OSError as e:
                self.assertEqual(e.errno, errno.ENOSPC)
        with unittest.mock.patch.object(subprocess, "Popen", side_effect=launch):
            with contextlib.ExitStack() as faults:
                for module in (hansa.desk, run, release):
                    faults.enter_context(unittest.mock.patch.object(module, "write_json", side_effect=save))
                    for name in ("write_bytes", "write_text"):
                        if hasattr(module, name):
                            original = getattr(module, name)

                            def other_write(*args, _write=original, **kwargs):
                                if persistent and full:
                                    raise OSError(errno.ENOSPC, "disk still full")
                                return _write(*args, **kwargs)
                            faults.enter_context(unittest.mock.patch.object(module, name, side_effect=other_write))
                event = self.desk.event

                def record_event(*args, **kwargs):
                    if persistent and full:
                        raise OSError(errno.ENOSPC, "disk still full")
                    return event(*args, **kwargs)
                faults.enter_context(unittest.mock.patch.object(self.desk, "event", side_effect=record_event))
                tick()
                self.assertTrue(full, ("did not reach the pid record", self.desk.meta(tid) if tid else
                                       release.get(self.desk, rid) if rid else run.read_try(self.desk, "a")))
                self.assertEqual(len(procs), 1)
                proc = procs[0]
                self.assert_start_record_group_stopped(proc)
                if persistent:
                    tick()  # another full-disk round cannot start it again either
                if restart:
                    self.desk = Desk(self.desk.root)  # serve restarted while the failure was still only in memory
                    d = Dispatcher(self.desk)
                    self.assertEqual(self.desk.failed_starts, {})
                    tick()  # writes still fail after the restart; no replacement can launch yet
                    self.assertEqual(len(procs), 1)
                    self.assert_start_record_group_stopped(proc)
            if restart and kind in ("worker", "verification"):
                self.desk.pause("observe ordinary recovery before dispatch")
                d.tick()
                m = self.desk.meta(tid)
                self.assertEqual((m["state"], m["phase"], m.get("pid")), ("queued", "", None), m)
                self.assertEqual(len(launches), 0 if recovering else 1)
                self.assert_start_record_group_stopped(proc)
                self.desk.resume()
            for _ in range(3):
                d.tick()  # space returned: retry the failure record, or ordinary recovery after restart
            reruns = restart and kind in ("worker", "verification", "check", "merge check")
            self.assertEqual(len(launches), (0 if recovering else 1) + int(reruns), "unexpected second start")
        if restart:
            self.assert_start_record_group_stopped(proc)
            if rid:
                r = release.get(self.desk, rid)
                self.assertEqual(r["state"], "failed", r)
                self.assertEqual(r["problem"], r["lost"])
                self.assertIn("hansa serve stopped as it started the release", r["lost"])
            elif kind == "try":
                t = run.read_try(self.desk, "a")
                self.assertEqual((t["phase"], t["ok"]), ("done", False), t)
                self.assertEqual((t["steps"]["check"]["ran"], t["steps"]["check"]["exit"]), (False, None))
                self.assertEqual(t["note"], "")
            else:
                m = self.desk.meta(tid)
                record = m["merge_check"] if kind == "merge check" else m
                self.assertEqual(m["state"], "merging" if kind == "merge check" else "running", m)
                self.assertEqual(record["pid"], procs[-1].pid)
                self.assertEqual(record["phase"], "running" if kind == "merge check" else
                                 "checking" if kind == "check" else "")
                self.assertIsNone(procs[-1].poll())
                self.assertTrue(run.group_running(procs[-1].pid))
            return
        if rid:
            r = release.get(self.desk, rid)
            self.assertEqual(r["state"], "failed", r)
            self.assertIn("it could not start: [Errno 28] start record disk full", r["problem"])
        elif kind == "try":
            t = run.read_try(self.desk, "a")
            self.assertEqual((t["phase"], t["ok"], t["steps"]), ("done", False, {}), t)
            self.assertIn("the try could not run: [Errno 28] start record disk full", t["note"])
        else:
            m = self.desk.meta(tid)
            if kind == "merge check":
                self.assertEqual((m["state"], m["merge_check"], m["merge_check_result"]["ok"]), ("done", None, False), m)
                self.assertIn("the merge check could not run: [Errno 28] start record disk full", m["merge_check_result"]["note"])
            else:
                self.assertEqual((m["state"], m["phase"], m.get("pid")), ("failed", "", None), m)
                prefix = "the lane's check could not run" if kind == "check" else "could not start"
                self.assertIn(prefix + ": [Errno 28] start record disk full", m["error"])

    def test_a_failed_start_record_stops_each_process_group_and_never_restarts_it(self):
        for kind in ("worker", "verification", "check", "merge check", "try", "release", "release fixed"):
            for persistent in (False, True):
                with self.subTest(kind=kind, persistent=persistent):
                    self.unrecordable_start(kind, False, persistent)

