                with self.subTest(case=case):
                    if case == "missing":
                        vmstat.unlink()
                    else:
                        vmstat.write_text("pgfault 20\n" if case == "no-line" else "oom_kill 20\n")
                    with unittest.mock.patch.object(account, "LINUX", case != "macos"):
                        self.assertIsNone(run.oom_kill())
