    @staticmethod
    def sandbox_of(argv):
        return json.loads(argv[argv.index("--settings") + 1]).get("sandbox")

    @staticmethod
    def denied_by(argv):
        return argv[argv.index("--disallowedTools") + 1:argv.index("--allowedTools")]

    def test_workers_run_in_the_sandbox_and_leave_git_history_to_hansa(self):
        seen = self.tmp / "argv.jsonl"
        s = self.desk.settings()
        s["lanes"]["a"]["env"] = {"FAKE_SHOW_ARGV": str(seen)}
        s["lanes"]["a"]["network"] = ["registry.npmjs.org", "*.pypi.org"]
        self.assertEqual(self.desk.save_settings(s), [])
        tid = self.desk.new_task("Add hello.txt")
        self.assertEqual(self.settle(Dispatcher(self.desk), tid)["state"], "done")
        argv = json.loads(seen.read_text().splitlines()[-1])
        box = self.sandbox_of(argv)
        self.assertEqual((box["enabled"], box["failIfUnavailable"], box["autoAllowBashIfSandboxed"],
                          box["allowUnsandboxedCommands"]), (True, True, True, False))
        self.assertEqual(box["network"], {"allowedDomains": ["registry.npmjs.org", "*.pypi.org"],
                                          "strictAllowlist": True})  # no local server without localhost
        for d in (self.desk.secrets_dir, self.desk.state_dir, Path.home() / ".ssh", Path.home() / ".claude.json"):
            self.assertIn(str(d), box["filesystem"]["denyRead"])
        self.assertEqual(box["credentials"]["envVars"], [{"name": "ANTHROPIC_AUTH_TOKEN", "mode": "deny"},
                                                         {"name": "ANTHROPIC_API_KEY", "mode": "deny"}])
        self.assertIn("claudeMdExcludes", json.loads(argv[argv.index("--settings") + 1]))  # one object, both in it
        # git history is kept by the sandbox too: the lane's linked worktree's git folders, worked out for real
        wt = Path(self.desk.meta(tid)["worktree"])
        common = (self.repo / ".git").resolve()
        own = Path(subprocess.run(["git", "rev-parse", "--absolute-git-dir"], cwd=wt, capture_output=True,
                                  text=True, check=True).stdout.strip()).resolve()
        self.assertNotEqual(own, common)  # a linked worktree has its own folder under the common one
        self.assertEqual(own.parent.parent, common)
        for f in ("objects", "refs", "packed-refs", "HEAD", "config", "hooks", "info", "logs"):
            self.assertIn(str(common / f), box["filesystem"]["denyWrite"])
        for f in ("HEAD", "logs", "commondir", "gitdir"):
            self.assertIn(str(own / f), box["filesystem"]["denyWrite"])
        self.assertNotIn(str(wt.resolve()), box["filesystem"]["denyWrite"])  # the worktree itself stays writable
        deny = self.denied_by(argv)
        for c in ("commit", "push", "merge", "reset", "stash", "switch", "branch", "checkout", "restore"):
            self.assertIn(f"Bash(git {c}:*)", deny)

        s = self.desk.settings()
        s["lanes"]["a"]["network"] = ["localhost"]
        self.assertEqual(self.desk.save_settings(s), [])
        with contextlib.redirect_stdout(io.StringIO()):
            main(["--desk", str(self.desk.root), "verify", tid])
        self.settle(Dispatcher(self.desk), self.desk.meta(tid)["verify"])
        argv = json.loads(seen.read_text().splitlines()[-1])
        self.assertIn("checking another worker's finished task", argv[argv.index("--append-system-prompt") + 1])
        box = self.sandbox_of(argv)
        self.assertEqual((box["enabled"], box["allowUnsandboxedCommands"]), (True, False))
        self.assertEqual(box["network"], {"allowedDomains": ["localhost"], "strictAllowlist": True,
                                          "allowLocalBinding": True})
        deny = self.denied_by(argv)
        self.assertIn("Bash(git commit:*)", deny)
        self.assertIn("Bash(git stash:*)", deny)
        self.assertNotIn("Bash(git checkout:*)", deny)  # a verification may put code back to see a test fail
        self.assertNotIn("Bash(git restore:*)", deny)
        self.assertIn("Bash(git checkout:*)", argv)
        self.assertIn(str(common / "refs"), box["filesystem"]["denyWrite"])

    @staticmethod
    def allowed_by(argv):
        return argv[argv.index("--allowedTools") + 1:]

    def test_workers_and_verifiers_run_a_probe_from_a_script_file_in_a_lane_with_no_allowed_commands(self):
        from hansa import run
        seen = self.tmp / "argv.jsonl"
        s = self.desk.settings()
        s["lanes"]["a"]["allow"] = []
        s["lanes"]["a"]["env"] = {"FAKE_SHOW_ARGV": str(seen)}
        self.assertEqual(self.desk.save_settings(s), [])
        tid = self.desk.new_task("Add hello.txt")
        self.assertEqual(self.settle(Dispatcher(self.desk), tid)["state"], "done")
        with contextlib.redirect_stdout(io.StringIO()):
            main(["--desk", str(self.desk.root), "verify", tid])
        vid = self.desk.meta(tid)["verify"]
        self.settle(Dispatcher(self.desk), vid)
        argvs = [json.loads(x) for x in seen.read_text().splitlines()]
        self.assertEqual(len(argvs), 2)
        for argv, who in zip(argvs, (tid, vid)):
            tmp = run.commands_tmp(self.desk.meta(who)["worker_tmps"][-1]["path"])
            told = " ".join(argv[argv.index("--append-system-prompt") + 1].split())
            self.assertIn("To try a line taken from a build or other script (one that holds rm, say), write it to a "
                          f"script file in your temporary folder and run that with sh: `sh {tmp}/probe.sh`, not "
                          '`bash -c "..."`. Claude Code refuses a shell -c it cannot check', told)
            # no allowed command of the lane's, yet sh with a script runs: Bash is let through in the sandbox
            self.assertIn("Bash", self.allowed_by(argv))
            self.assertFalse([r for r in self.denied_by(argv) if r.startswith(("Bash(sh", "Bash(bash", "Bash(/bin"))])
            box = self.sandbox_of(argv)
            self.assertEqual((box["autoAllowBashIfSandboxed"], box["allowUnsandboxedCommands"]), (True, False))
        probe = self.tmp / "probe"
        probe.mkdir()
        (probe / "probe.sh").write_text(f'mkdir -p "{probe}/out" && touch "{probe}/out/x" && rm -r "{probe}/out" '
                                        '&& echo ran\n')
        r = subprocess.run(["sh", str(probe / "probe.sh")], capture_output=True, text=True)
        self.assertEqual((r.returncode, r.stdout), (0, "ran\n"), r.stderr)
        self.assertFalse((probe / "out").exists())

    def test_show_and_status_give_the_effort_each_run_started_with_and_where_it_came_from(self):
        from hansa import run
        seen = self.tmp / "argv.jsonl"
        s = self.desk.settings()
        s["lanes"]["a"]["env"] = {"FAKE_SHOW_ARGV": str(seen)}
        self.assertEqual(self.desk.save_settings(s), [])
        d = Dispatcher(self.desk)
        plain = self.desk.new_task("Add hello.txt")
        self.settle(d, plain)
        self.assertNotIn("--effort", json.loads(seen.read_text().splitlines()[-1]))
        self.assertIn(f"{plain} · done · lane a · claude (opus, claude's default effort) · ", views.show_text(self.desk, plain))
        asked = self.desk.new_task("Add hello.txt", effort="max")
        self.settle(d, asked)
        argv = json.loads(seen.read_text().splitlines()[-1])
        self.assertEqual(argv[argv.index("--effort") + 1], "max")
        self.assertIn(" · claude (opus, effort max from the task's --effort) · ", views.show_text(self.desk, asked))
        s = self.desk.settings()
        s["providers"]["claude"]["effort"] = "high"
        self.assertEqual(self.desk.save_settings(s), [])
        own = self.desk.new_task("Add hello.txt")
        self.settle(d, own)
        self.assertIn(" · claude (opus, effort high from the provider's default) · ", views.show_text(self.desk, own))
        # an endpoint that is not Claude's own may ignore it
        s = self.desk.settings()
        s["providers"]["mimo"] = {"kind": "compatible", "model": "mimo-x", "effort": "low", "base_url": "https://example.invalid"}
        s["lanes"]["a"]["providers"] = ["mimo"]
        self.assertEqual(self.desk.save_settings(s), [])
        self.desk.write_key("mimo", "sk-test-effort-0001")
        compat = self.desk.new_task("Add hello.txt")
        self.settle(d, compat)
        said = ("mimo (mimo-x, effort low from the provider's default; its endpoint is not Claude's own and may ignore "
                "effort)")
        self.assertIn(f" · {said} · ", views.show_text(self.desk, compat))
        # hansa status, of a run under way
        self.desk.update(compat, state="running", phase="", pid=os.getpid(), pid_start=run.proc_start(os.getpid()),
                         started=time.time())
        st = views.status(self.desk)
        row = next(x for x in st["running"] if x["id"] == compat)
        self.assertEqual((row["effort"], row["effort_from"]), ("low", "provider"))
        self.assertIn(f"  {compat} a on {said}, 0 min: ", views.status_text(st))
        self.desk.update(compat, state="done", pid=None)
        # an earlier run started otherwise names its own; one started as the last does not repeat it
        keep = run.run_numbers(self.desk.meta(asked), {})
        self.assertEqual((keep["model"], keep["effort"], keep["effort_from"]), ("opus", "max", "task"))
        self.desk.update(own, attempts=[{"provider": "claude", "at": time.time(), "error": "it stopped",
                                         "kind": "refused", **keep},
                                        {"provider": "claude", "at": time.time(), "error": "again", "kind": "refused",
                                         **run.run_numbers(self.desk.meta(own), {})}])
        shown = views.show_text(self.desk, own)
        self.assertIn("earlier try on claude (opus, effort max from the task's --effort): it stopped\n", shown)
        self.assertIn("earlier try on claude: again\n", shown)

    def test_hansa_help_with_a_command_prints_that_commands_help(self):
        out = io.StringIO()
        with contextlib.redirect_stdout(out), self.assertRaises(SystemExit):
            main(["verify", "--help"])
        self.assertEqual(self.hansa_out("help", "verify"), out.getvalue())
        out = io.StringIO()
        with contextlib.redirect_stdout(out), self.assertRaises(SystemExit):
            main(["lane", "add", "--help"])
        self.assertEqual(self.hansa_out("help", "lane", "add"), out.getvalue())
        self.assertTrue(self.hansa_out("help", "card").startswith("# The card"))
        with self.assertRaises(SystemExit) as e:
            self.hansa_out("help", "nosuch")
        self.assertIn("no command or topic nosuch; hansa help topics lists the topics", str(e.exception.code))
        # alone: an index, not the card: every command, then every topic with what it holds
        index = self.hansa_out("help")
        self.assertLessEqual(len(index.splitlines()), 40)
        self.assertNotIn("# The card", index)
        for name in ("add", "merge", "lane (add, set, target, brief, remove, try)", "disk-floor", "coordinator"):
            self.assertIn(name, index)
        self.assertNotIn("notify-follow", index)  # the hidden ones stay hidden
        self.assertIn(self.hansa_out("help", "topics"), index)
        for name, (_, _, holds) in cli.TOPICS.items():
            self.assertRegex(self.hansa_out("help", "topics"), rf"\n  {re.escape(name)} +{re.escape(holds)}\n")
        # hansa coordinator --help is hansa's own help, and starts nothing
        out = io.StringIO()
        with unittest.mock.patch("hansa.cli.cmd_coordinator") as started, contextlib.redirect_stdout(out):
            main(["--desk", str(self.desk.root), "coordinator", "--help"])
        started.assert_not_called()
        self.assertIn("--clear-daily HH-HH", out.getvalue())
        self.assertIn("claude --help lists them", " ".join(out.getvalue().split()))
        self.assertEqual(out.getvalue(), self.hansa_out("help", "coordinator"))

