    def test_status_and_the_page_look_at_what_workers_may_not_read_once_a_minute_and_runs_every_time(self):
        from hansa import desk as hdesk, run
        secret = str(self.tmp.resolve() / "keys")
        s = self.desk.settings()
        s["workers_may_not_read"] = [secret]
        write_json(self.desk.settings_path, s)
        looks = []
        real = hdesk.no_read_parts

        def counted(*a, **k):
            looks.append(1)
            return real(*a, **k)
        with unittest.mock.patch("hansa.desk.no_read_parts", counted):
            st = views.status(self.desk)
            views.status(self.desk)
            public_settings(self.desk)
            self.assertEqual(len(looks), 1)  # the polls and Settings share one look
            st["no_read_left_out"].append("changed by a caller")  # a copy: what is kept is not changed
            self.assertEqual(views.status(self.desk)["no_read_left_out"], [])
            s["workers_may_not_read"] = [secret, str(self.repo.resolve())]  # the list changed: looked at again
            write_json(self.desk.settings_path, s)
            self.assertEqual(len(views.status(self.desk)["no_read_left_out"]), 1)
            self.assertEqual(len(looks), 2)
            (self.desk.root / "worktrees" / "x").mkdir(parents=True)  # a worktree made: again
            views.status(self.desk)
            self.assertEqual(len(looks), 3)
            with unittest.mock.patch.dict(os.environ, {"PATH": f"/opt/elsewhere{os.pathsep}{os.environ['PATH']}"}):
                views.status(self.desk)  # another PATH: again
            self.assertEqual(len(looks), 4)
            with unittest.mock.patch("hansa.desk.time.monotonic", return_value=time.monotonic() + hdesk.NO_READ_KEEP):
                views.status(self.desk)  # a minute on: again
            self.assertEqual(len(looks), 5)
        # a run checks the list itself as it starts, whatever the page has kept
        with unittest.mock.patch("hansa.desk.no_read_parts", counted), \
                unittest.mock.patch("hansa.run.no_read_parts", counted):
            run.no_read(self.desk)
        self.assertEqual(len(looks), 6)

    def test_an_entry_left_out_for_a_lanes_repository_is_said_in_status_and_on_the_page(self):
        s = self.desk.settings()
        s["workers_may_not_read"] = [str(self.repo.resolve())]
        write_json(self.desk.settings_path, s)
        st = views.status(self.desk)
        self.assertEqual(st["no_read_stop"], "")
        self.assertEqual(len(st["no_read_left_out"]), 1)
        text = views.status_text(st)
        for x in (f"what workers may not read, entry left out: {self.repo.resolve()}: it is {self.repo.resolve()}, "
                  "lane a's repository", "that folder is open to the runs of that lane"):
            self.assertIn(x, text)
        def timeless(t):  # the text says the time: the minute may turn between the two calls
            return re.sub(r"now \d\d:\d\d", "now", t)
        again = views.status_text(views.status(self.desk))
        self.assertIn("what workers may not read, entry left out", again)  # every time, not once
        self.assertEqual(timeless(again), timeless(text))
        shown = public_settings(self.desk)
        self.assertEqual((shown["deny_stops"], shown["no_read_stop"]), ([], ""))
        self.assertEqual(len(shown["deny_skipped"]), 1)
        self.assertIn("that folder is open to the runs of that lane", shown["deny_skipped"][0])
        self.assertIn(str(self.repo.resolve()), shown["deny_skipped"][0])
        ui = (Path(__file__).resolve().parent.parent / "hansa" / "ui.html").read_text()
        self.assertIn("st.no_read_left_out", ui)
        # a run still starts
        tid = self.desk.new_task("Add hello.txt")
        self.assertEqual(self.settle(Dispatcher(self.desk), tid)["state"], "done")

    def test_a_lanes_write_list_change_is_recorded_for_the_principal(self):
        self.assertNotIn("Tell the principal", self.hansa("lane", "set", "a", "write"))  # [] -> []: no change
        self.assertEqual(self.events("lane_write_changed"), [])
        out = self.hansa("lane", "set", "a", "write", "/opt/m2")
        self.assertIn('write: [] -> ["/opt/m2"]', out)
        self.assertIn("Tell the principal", out)
        self.assertEqual(len(self.events("lane_write_changed")), 1)
        self.assertNotIn("Tell the principal", self.hansa("lane", "set", "a", "write", "/opt/m2"))
        self.hansa("lane", "set", "a", "write", "/opt/m2", "/opt/npm")
        self.assertNotIn("Tell the principal", self.hansa("lane", "set", "a", "write", "/opt/npm", "/opt/m2"))
        self.assertEqual(len(self.events("lane_write_changed")), 2)
        self.assertIn("  folders a worker may also write (a build or test tool's cache): /opt/npm, /opt/m2\n",
                      views.explain_text(self.desk, "lane", "a"))
        self.assertIn("Tell the principal", self.hansa("lane", "set", "a", "write"))
        self.assertEqual([(e["lane"], e["old"], e["new"]) for e in self.events("lane_write_changed")],
                         [("a", [], ["/opt/m2"]), ("a", ["/opt/m2"], ["/opt/m2", "/opt/npm"]),
                          ("a", ["/opt/npm", "/opt/m2"], [])])
        self.assertIn("folders a worker may also write (a build or test tool's cache): none",
                      views.explain_text(self.desk, "lane", "a"))

    def test_the_git_deny_patterns_keep_the_same_names_as_macos_reads_their_classes(self):
        from hansa import run

        def listed(folder, names):  # others_than as it was: each class listing every character it keeps
            out = []

            def walk(start, rest):
                nexts = sorted({s[0] for s in rest if s})
                out.append(f"{folder}/{start}[{''.join(c for c in run.NAME_CHARS if c not in nexts)}"
                           f"{'' if '-' in nexts else '-'}]*")
                if start and "" not in rest:
                    out.append(f"{folder}/{start}")
                for c in nexts:
                    walk(start + c, [s[1:] for s in rest if s and s[0] == c])
            walk("", list(names))
            return out
        for i, name in enumerate(("o0", "a-x", "ab")):  # other worktrees, two whose names start as the lane's does
            sh("git", "worktree", "add", "-q", "-b", f"task/t09{i}", str(self.tmp / name), cwd=self.repo)
        lane = self.desk.settings()["lanes"]["a"]
        wt = run.prepare(self.desk, "a", lane, self.desk.meta(self.desk.new_task("Work")))[0]
        cases = run._git_open(wt)
        common = run.git_folders(wt)[0]
        self.assertIn((common, ("worktrees",)), cases)  # the common folder with worktrees open
        self.assertIn((common / "worktrees", (wt.name,)), cases)  # the worktree's folder among the others
        chars = run.NAME_CHARS + "-" + "^!/ ~@é`{"  # and a few outside them, ~ ` { after the small letters

        def elements(cls):  # as macOS counts them: a character (\. too, a leading - too) or a range
            return len(re.findall(r"\\.|.-.|.", cls))
        for folder, names in cases:
            old, new = listed(folder, names), run.others_than(folder, names)
            self.assertEqual([a for a in old if "[" not in a], [b for b in new if "[" not in b], folder)
            held = {}  # each start: what its classes hold together
            for b in new:
                if "[" not in b:
                    continue
                cls = b[b.rindex("[") + 1:b.rindex("]")]
                held.setdefault(b[:b.rindex("[")], set()).update(x for x in run.NAME_CHARS if re.fullmatch(f"[{cls}]", x))
                self.assertNotRegex(cls, "012|ABC|abc|xyz", b)  # runs, not every character one by one
                self.assertTrue(re.fullmatch(r"-?([0-9A-Za-z](-[0-9A-Za-z])?)*\.?_?", cls), b)  # - first, ranges, . _
                self.assertLessEqual(elements(cls), run.CLASS_MAX, b)  # more, and macOS drops the class
            for start, chars_held in held.items():  # a letter is left out in both cases
                self.assertEqual({x.lower() for x in chars_held if x.isalpha()},
                                 {x for x in chars_held if x.islower()}, start)
            starts = {n[:k] for n in names for k in range(len(n) + 1)}
            for start in starts:
                for c in chars:
                    for name in (start + c, start + c + "x"):
                        p = f"{folder}/{name}"
                        # what macOS keeps by the new is what the old kept of the name in small letters
                        self.assertEqual(any(re.match(sandbox_glob(a), f"{folder}/{name.lower()}") for a in old),
                                         any(macos_match(b, p) for b in new), (folder, name))
        self.assertEqual(run.CLASS_MAX, 15)
        self.assertIn("[-0-9A-SU-Za-su-z._]*", " ".join(run.others_than(common / "refs" / "heads", ("task",))))
        # as measured with macOS's sandbox: for ("a",), what stays open and what is kept
        rules = run.others_than(Path("/W"), ("a",))
        self.assertEqual(rules[:2], ["/W/[-0-9B-Zb-z._]*", "/W/a[-0-9A-Za-z._]*"])
        kept = lambda n: any(macos_match(r, f"/W/{n}") for r in rules)
        for n in ("a/x", "a", "A/x"):
            self.assertFalse(kept(n), n)
        for n in ("b", "-x", ".x", "_x", "0x", "Zx", "Bx", "ab", "a-", "a.", "a_", "aB", "a9"):
            self.assertTrue(kept(n), n)

    def refusing_srt(self, rule: str) -> None:
        """The stand-in srt, refusing a try of a run's sandbox (on /usr/bin/true) whose `settings` hold for this
        rule, as macOS refused one: with sandbox-exec's line and exit 71."""
        srt = self.tmp / "bin" / "srt"
        srt.write_text(srt.read_text().replace("os.execvp(", (
            f"if args[-1] == '/usr/bin/true' and ({rule}):\n"
            "    sys.stderr.write('sandbox-exec: sandbox_apply: Invalid argument\\n')\n"
            "    sys.exit(71)\nos.execvp("), 1))

    def test_a_worker_whose_sandbox_srt_refuses_does_not_start_and_its_task_is_held(self):
        from hansa import alert, run
        self.refusing_srt("settings['filesystem']['denyRead']")
        with unittest.mock.patch("hansa.alert.command", lambda s: "true"):
            tid = self.desk.new_task("Add hello.txt")
            d = Dispatcher(self.desk)
            d.tick()
            m = self.desk.meta(tid)
            self.assertEqual(m["state"], "queued", m)  # held, not failed
            self.assertEqual(m["held"]["part"], "the deny-read list")
            self.assertIn("sandbox-exec: sandbox_apply: Invalid argument (exit 71)", m["held"]["why"])
            self.assertEqual(m.get("attempts", []), [])
            self.assertFalse(m.get("launch"))
            self.assertFalse((self.desk.worktrees_dir / "a" / "hello.txt").exists())  # the worker never ran
            self.assertEqual(self.events("task_started"), [])
            shown = views.status_text(views.status(self.desk))
            self.assertIn("UNABLE TO RUN", shown)
            self.assertIn("the deny-read list", shown)
            self.assertIn("HELD: lane a cannot run", waiting_reason(self.desk, self.desk.settings(), m, set()))
            self.assertIn("the deny-read list", self.hansa("explain", "server"))
            tried = len(self.srt_calls(sandbox=True))
            d.tick()  # the same settings: not tried again, and the task waits
            self.assertEqual(len(self.srt_calls(sandbox=True)), tried)
            self.assertEqual(self.desk.meta(tid)["state"], "queued")
            run.SANDBOX_TRIES.clear()  # as a restart: tried again, held again, and not alerted again
            Dispatcher(self.desk).tick()
            self.assertGreater(len(self.srt_calls(sandbox=True)), tried)
            self.assertEqual(self.desk.meta(tid)["state"], "queued")
            said = [x["text"] for x in alert.queued(self.desk) if x["kind"] == "sandbox"]
            self.assertEqual(len(said), 1, said)
            self.assertIn("lane a cannot run", said[0])
            self.assertIn("the deny-read list", said[0])

