    def test_background_work_still_running_when_the_worker_ended_is_said(self):
        line = ("the worker ended while its background work was still running ({}); its report may be "
                "incomplete: read the changes before merging")
        for kind, what in (("bg-cmd", "Run the full test suite"), ("bg-agent", "Review the badge change")):
            with self.subTest(kind):  # resumed once, and it left background work running again
                self.assertEqual(self.transcript_run(kind + "-again"), "Report after the resume: the suite passes.\n")
                tid = self.desk.tasks()[-1]["id"]
                m = self.desk.meta(tid)
                self.assertEqual(m["state"], "done")  # not failed for it: the work may be complete
                self.assertIn(line.format(what), views.show_text(self.desk, tid))
                self.assertTrue(notify.task_line(self.desk, m).endswith(line.format(what)))
                self.transcript_run(kind + "-noticed")
                tid = self.desk.tasks()[-1]["id"]
                self.assertNotIn("background work was still running", views.show_text(self.desk, tid))
                self.assertNotIn("background work", notify.task_line(self.desk, self.desk.meta(tid)))

    def test_a_worker_that_ended_with_background_work_running_is_resumed_once_and_then_reports(self):
        from hansa import run
        seen = self.tmp / "resumed.jsonl"
        report = self.transcript_run("bg-cmd", env={"FAKE_RESUMED": str(seen)})
        self.assertEqual(report, "Report after the resume: the suite passes.\n")
        tid = self.desk.tasks()[-1]["id"]
        m = self.desk.meta(tid)
        self.assertEqual(m["state"], "done", m)
        calls = [json.loads(x) for x in seen.read_text().splitlines()]
        self.assertEqual(len(calls), 1)
        argv, prompt = calls[0]["argv"], " ".join(calls[0]["prompt"].split())
        self.assertEqual(argv[argv.index("--resume") + 1], m["session_id"])
        self.assertNotIn("--session-id", argv)
        self.assertIn("Run a long build or test suite in the foreground",  # its own run's Bash limits as well
                      argv[argv.index("--append-system-prompt") + 1])
        self.assertIn("Run the full test suite", prompt)
        self.assertIn("in the foreground, in one Bash call", prompt)
        self.assertIn("This is the only time hansa resumes you", prompt)
        self.assertEqual(calls[0]["env"]["HANSA_TASK"], tid)
        self.assertEqual(calls[0]["env"]["BASH_MAX_TIMEOUT_MS"], str(60000 * 240))
        self.assertEqual(calls[0]["env"]["BASH_DEFAULT_TIMEOUT_MS"], str(60000 * 10))
        self.assertIn(f"the Bash tool's timeout, in milliseconds, up to {60000 * 240}: 240 minutes", prompt)
        self.assertEqual(m["resumed"]["left"], ["Run the full test suite"])
        self.assertEqual(m["background_left"], [])  # the first run's work was run again, in the foreground
        self.assertEqual(m["turns"], 5 + 2)  # both runs'
        self.assertEqual(m["usage"]["mimo-x"]["in"], 10)
        self.assertNotIn("background work was still running", views.show_text(self.desk, tid))
        self.assertFalse((self.desk.state_dir / "runs" / tid / run.RESUME_ARGV).exists())
        self.assertIn(("task_resumed", tid), [(e["event"], e.get("task")) for e in
                                              map(json.loads, self.desk.events_path.read_text().splitlines())])
        # It ends with background work running a second time: not resumed again, and the task says so
        seen.unlink()
        self.transcript_run("bg-cmd-again", env={"FAKE_RESUMED": str(seen)})
        tid = self.desk.tasks()[-1]["id"]
        m = self.desk.meta(tid)
        self.assertEqual(m["state"], "done", m)
        self.assertEqual(len(seen.read_text().splitlines()), 1)
        self.assertEqual(m["background_left"], ["Run the full test suite"])
        # Work seen to end, or no background work at all: no resume
        seen.unlink()
        self.transcript_run("bg-cmd-noticed", env={"FAKE_RESUMED": str(seen)})
        self.transcript_run("plain", env={"FAKE_RESUMED": str(seen)})
        self.assertFalse(seen.exists())

    def test_a_cancel_landing_while_a_resume_is_prepared_prevents_the_resume(self):
        from hansa import run
        seen = self.tmp / "resumed.jsonl"
        s = self.desk.settings()
        s["providers"]["mimo"] = {"kind": "compatible", "model": "mimo-x", "effort": "", "base_url": "https://x"}
        s["lanes"]["a"]["providers"] = ["mimo"]
        s["lanes"]["a"]["env"] = {"FAKE_TRANSCRIPT": "bg-cmd", "FAKE_RESUMED": str(seen)}
        self.assertEqual(self.desk.save_settings(s), [])
        self.desk.write_key("mimo", "sk-test-01")
        tid = self.desk.new_task("Fix the badge")
        real_sweep, cancelled = run.sweep, []

        def cancelled_meanwhile(desk, task):
            # The worker has ended, but resume has not yet rechecked the task under the desk lock.
            desk.update(task, cancel=True)
            cancelled.append(task)
            return real_sweep(desk, task)
        with unittest.mock.patch.object(run, "sweep", side_effect=cancelled_meanwhile):
            m = self.settle(Dispatcher(self.desk), tid)
        self.assertIn(tid, cancelled)
        self.assertEqual(m["state"], "cancelled", m)
        self.assertIsNone(m.get("resumed"))
        self.assertFalse(seen.exists())
        self.assertEqual(self.events("task_resumed"), [])

    def test_read_bounded_drops_a_margin_so_no_part_of_a_key_survives_a_cut(self):
        from hansa import run
        key = b"sk-registry-0123456789abcdef"
        self.desk.secrets_dir.mkdir(parents=True, exist_ok=True)
        (self.desk.secrets_dir / "registry.key").write_bytes(key)
        half, log = 8192, self.tmp / "bounded.log"
        # Keys straddle both cuts in a line with no newline; redaction alone cannot remove their fragments.
        body = b"x" * (half - 10) + key + b"y" * (3 * half) + key + b"z" * (half - 10)
        for first, last in ((b"", b""), (b"x\n", b""), (b"", b"\nz"), (b"x\n", b"\nz")):
            with self.subTest(first=first, last=last):
                log.write_bytes(first + body + last)
                text = self.desk.redact(run.read_bounded(log, half, half))
                kept = re.sub(r"\n\[hansa: [^\]]*\]\n", "", text)
                self.assertLessEqual(set(kept), set("xyz\n"), "a part of the key is left")
                self.assertIn("bytes left out here", text)
                self.assertLess(len(text), 2 * half + 300)
                if not first or not last:
                    self.assertIn(f"with {run.OUTPUT_MARGIN} bytes on each side of a cut inside a line", text)
        big = self.tmp / "big.log"  # what publish reads of a log hansa did not write itself is bounded too
        with open(big, "wb") as f:
            f.write(b"first line\n")
            f.truncate(2 ** 30)
            f.seek(0, 2)
            f.write(b"\nlast line\n")
        text = run.read_bounded(big, 2 ** 20, 2 ** 20)
        self.assertLess(len(text), 2 ** 21 + 200)
        self.assertTrue(text.startswith("first line\n") and text.endswith("\nlast line\n"))

    @unittest.mock.patch("hansa.run.PROBE_MINUTES", 0, create=True)
    def test_a_retry_after_a_resumed_run_dropped_its_connection_keeps_its_own_record(self):
        # Resumed, the run ends on a dropped connection: the task is queued again, in a new session, which also
        # leaves background work. That try is resumed in its own right, and nothing of the first try's carries.
        seen, drop = self.tmp / "resumed.jsonl", self.tmp / "dropped"
        report = self.transcript_run("bg-cmd", env={"FAKE_RESUMED": str(seen), "FAKE_RESUME_DROP": str(drop)})
        self.assertEqual(report, "Report after the resume: the suite passes.\n")
        tid = self.desk.tasks()[-1]["id"]
        m = self.desk.meta(tid)
        self.assertTrue(drop.exists())
        calls = [json.loads(x) for x in seen.read_text().splitlines()]
        self.assertEqual(len(calls), 2)  # each try resumed once
        first, second = [c["argv"][c["argv"].index("--resume") + 1] for c in calls]
        self.assertNotEqual(first, second)
        self.assertEqual(second, m["session_id"])
        self.assertEqual(m["resumed"]["left"], ["Run the full test suite"])
        self.assertEqual(m["background_left"], [])
        self.assertEqual(m["turns"], 5 + 2)  # this try's runs only
        [a] = m["attempts"]
        self.assertEqual((a["kind"], a["turns"]), ("network", 5 + 1))  # the first try's, kept in its attempt
        self.assertIn("usage", a)
        from hansa import run
        for text in ("API Error: Unable to connect to API. Check your internet connection",
                     "API Error: Unable to connect to API (ENETUNREACH)", "connect ENETUNREACH 10.0.0.1:443 (ENETUNREACH)",
                     "Connection lost while your computer was asleep"):
            self.assertTrue(run.network_reason({"is_error": True, "result": text}, ""), text)
        # a certificate the machine does not trust is not a dropped connection: running it again changes nothing
        self.assertEqual(run.network_reason({"is_error": True, "result": "API Error: Unable to connect to API: "
                                             "SSL certificate has expired"}, ""), "")

    def test_background_agents_with_notices_are_not_listed_as_still_running(self):
        # Four background agents each have a "completed" notice; a test run has none.
        from hansa import run
        home = self.tmp / "t0061-home"
        rec = home / "projects" / "-work" / "s61.jsonl"
        rec.parent.mkdir(parents=True)
        agents = [("aaeaa54cef8eb6489", "Review the catalog schema"), ("a1b2c3d4e5f60718", "Review the checkout flow"),
                  ("a9f8e7d6c5b4a392", "Review the receipt text"), ("a0c1e2a3b4c5d6e7", "Read the page texts")]
        rows, notices = [], []
        for i, (aid, what) in enumerate(agents):
            said, result = BG_AGENT(aid, what)
            rows += [{"type": "assistant", "message": {"id": f"m{i}", "content": [
                         {"type": "tool_use", "id": f"toolu_{i}", "name": "Agent", "input": {
                             "description": what, "prompt": "Do it", "subagent_type": "general-purpose"}}]}},
                     {"type": "user", "toolUseResult": result, "message": {"role": "user", "content": [
                         {"type": "tool_result", "tool_use_id": f"toolu_{i}",
                          "content": [{"type": "text", "text": said}]}]}}]
            notices.append(BG_NOTICE(aid, what))
        command = "python3 -m unittest tests.test_hansa 2>&1 | tail -15"
        said, result = BG_BASH("b2w1815is")
        rows += [{"type": "assistant", "message": {"id": "mb", "content": [
                     {"type": "tool_use", "id": "toolu_b", "name": "Bash", "input": {
                         "command": command, "run_in_background": True}}]}},
                 {"type": "user", "toolUseResult": result, "message": {"role": "user", "content": [
                     {"type": "tool_result", "tool_use_id": "toolu_b", "content": said}]}}]
        for n in notices:  # each notice is written twice: queued, then as the user row that opens the turn
            rows += [{"type": "queue-operation", "operation": "enqueue", "sessionId": "s61", "content": n},
                     {"type": "user", "message": {"role": "user", "content": n}}]
        rows.append({"type": "assistant", "message": {"id": "mz", "content": [
            {"type": "text", "text": "I'm waiting for the full test suite to finish before I write the report."}]}})
        rec.write_text("".join(json.dumps(r) + "\n" for r in rows))
        self.assertEqual(run.background_left(home, "s61"), [command])
        # Without the structured ids, the text is read: still only the test run
        for r in rows:
            r.pop("toolUseResult", None)
        rec.write_text("".join(json.dumps(r) + "\n" for r in rows))
        self.assertEqual(run.background_left(home, "s61"), [command])

    def verify_lane_task(self):
        d = Dispatcher(self.desk)
        tid = self.desk.new_task("Add hello.txt", lane="a")
        self.assertEqual(self.settle(d, tid)["state"], "done")
        return d, tid

    def add_verify_lane(self, name="v1", *lanes):
        self.hansa("lane", "add", name, "--like", "a")
        self.hansa("lane", "set", name, "verify_for", *(lanes or ("a",)))

    def assert_verifies_on(self, tid, lane, automatic=True):
        out = self.hansa("verify", tid)
        vid = self.desk.meta(tid)["verify"]
        self.assertEqual(self.desk.meta(vid)["lane"], lane)
        if automatic:
            self.assertIn(f"{vid} queued on lane {lane}", out)
            self.assertIn(f"chosen as a verify lane for lane a", out)
        return vid

    def test_verify_lane_free_lane_runs_the_verification(self):
        d, tid = self.verify_lane_task()
        self.add_verify_lane()
        self.hansa("lane", "set", "v1", "env", "FAKE_VERDICT=holds")
        vid = self.assert_verifies_on(tid, "v1")
        v = self.settle(d, vid)
        self.assertEqual((v["lane"], v["kind"], v["verdict"]), ("v1", "verify", "holds"))

    def test_verify_lane_prefers_free_over_running(self):
        _, tid = self.verify_lane_task()
        self.add_verify_lane("v1")
        self.add_verify_lane("v2")
        busy = self.desk.new_task("checking", lane="v1", kind="verify")
        self.desk.update(busy, state="running")
        vid = self.assert_verifies_on(tid, "v2")
        self.desk.update(vid, state="done")
        self.desk.update(busy, state="queued")
        self.assert_verifies_on(tid, "v2")  # queued work also prevents a lane being free

    def test_verify_lane_busy_lanes_choose_fewest_queued(self):
        _, tid = self.verify_lane_task()
        for lane, queued in (("v1", 2), ("v2", 1)):
            self.add_verify_lane(lane)
            busy = self.desk.new_task("checking", lane=lane, kind="verify")
            self.desk.update(busy, state="running")
            for _ in range(queued):
                self.desk.new_task("waiting", lane=lane, kind="verify")
        self.assert_verifies_on(tid, "v2")

    def test_verify_lane_free_lanes_follow_settings_order(self):
        _, tid = self.verify_lane_task()
        self.add_verify_lane("v2")
        self.add_verify_lane("v1")
        first = next(n for n, ln in self.desk.settings()["lanes"].items() if ln.get("verify_for"))
        vid = self.assert_verifies_on(tid, first)
        self.desk.update(vid, state="done")
        for lane in ("v1", "v2"):
            busy = self.desk.new_task("checking", lane=lane, kind="verify")
            self.desk.update(busy, state="running")
        self.assert_verifies_on(tid, first)  # ties among busy lanes follow the same order

    def test_verify_without_verify_lanes_uses_own_lane(self):
        _, tid = self.verify_lane_task()
        self.assert_verifies_on(tid, "a", automatic=False)

    def test_verify_lane_explicit_lane_overrides_automatic_choice(self):
        _, tid = self.verify_lane_task()
        self.hansa("lane", "add", "b", "--like", "a")
        self.add_verify_lane("v1")
        self.add_verify_lane("v2", "b")  # an explicit verify lane need not list the task's lane
        for lane in ("b", "v2"):
            with self.subTest(lane=lane):
                out = self.hansa("verify", tid, "--lane", lane)
                vid = self.desk.meta(tid)["verify"]
                self.assertEqual(self.desk.meta(vid)["lane"], lane)
                self.assertIn(f"{vid} queued on lane {lane}:", out)
                self.assertNotIn("chosen as a verify lane", out)
                self.desk.update(vid, state="done", verdict="holds")
        self.hansa("lane", "set", "v1", "verify_for", "none")
        self.assert_verifies_on(tid, "a", automatic=False)  # v2 verifies b, so it does not match a

    def test_verify_lane_refuses_add_retry_and_direct_work(self):
        _, tid = self.verify_lane_task()
        self.add_verify_lane()
        before = self.desk.tasks()
        for args in (("add", "--lane", "v1", "work"), ("retry", tid, "--lane", "v1", "again")):
            with self.subTest(args=args), self.assertRaises(SystemExit) as e:
                self.hansa(*args)
            self.assertIn("lane v1 is a verify lane and takes only verifications", str(e.exception))
            self.assertIn("nothing was queued", str(e.exception))
            self.assertEqual(self.desk.tasks(), before)
        with self.assertRaises(SystemExit) as e:
            self.desk.new_task("direct work", lane="v1")
        self.assertIn("lane v1 is a verify lane and takes only verifications", str(e.exception))
        self.assertEqual(self.desk.tasks(), before)

    def test_verify_lane_automatic_work_assignment_and_dispatch_guards(self):
        from hansa import run
        self.add_verify_lane("0")  # first ordinary automatic candidate before this feature
        s = self.desk.settings()
        s["providers"]["verifier"] = dict(s["providers"]["claude"])
        s["lanes"]["0"]["providers"] = ["verifier"]
        self.assertEqual(self.desk.save_settings(s), [])
        d = Dispatcher(self.desk)
        tid = self.desk.new_task("Add hello.txt")
        self.desk.set_provider_state("verifier", unreachable_since=now(), unreachable_reason="offline")
        self.assertIn("0 tasks wait for it", views.provider_status_problem(
            self.desk, self.desk.settings(), "verifier", [self.desk.meta(tid)]))
        self.assertIn("ready for lane a", waiting_reason(self.desk, self.desk.settings(), self.desk.meta(tid), set()))
        self.assertIsNone(run.start(self.desk, tid, "0", "claude"))
        self.assertEqual(self.desk.meta(tid)["state"], "queued")
        self.assertEqual(self.settle(d, tid)["lane"], "a")
        # An old or hand-written queue entry cannot bypass the dispatcher or its explanation.
        stale = self.desk.new_task("work")
        self.desk.update(stale, lane="0")
        d.tick()
        self.assertEqual(self.desk.meta(stale)["state"], "queued")
        self.assertIn("lane 0 is a verify lane and takes only verifications",
                      waiting_reason(self.desk, self.desk.settings(), self.desk.meta(stale), set()))
        self.assertIn("1 task waits for it", views.provider_status_problem(
            self.desk, self.desk.settings(), "verifier", [{**self.desk.meta(stale), "kind": "verify"}]))
        self.desk.set_provider_state("verifier", unreachable_since=0, unreachable_reason="")
        self.hansa("lane", "set", "0", "verify_for", "none")
        self.hansa("lane", "set", "a", "verify_for", "0")
        self.desk.update(stale, lane="")
        self.assertIn("ready for lane 0", waiting_reason(self.desk, self.desk.settings(), self.desk.meta(stale), set()))

    def test_verify_lane_dispatcher_skips_ready_first_candidate(self):
        from hansa import run
        self.add_verify_lane("0")
        s = self.desk.settings()
        self.assertEqual(sorted(s["lanes"])[0], "0")
        self.assertEqual(provider_problem(self.desk, s, "claude"), "")
        tid = self.desk.new_task("Unassigned work")
        # Observe the dispatcher's choice independently of start's own guard.
        with unittest.mock.patch.object(run, "start", return_value=None) as start:
            Dispatcher(self.desk).tick()
        start.assert_called_once_with(self.desk, tid, "a", "claude")
        self.assertEqual(self.desk.meta(tid)["state"], "queued")

    def test_verify_lane_waiting_reason_excludes_ready_first_candidate(self):
        self.add_verify_lane("0")
        s = self.desk.settings()
        s["providers"]["verifier"] = dict(s["providers"]["claude"])
        s["lanes"]["0"]["providers"] = ["verifier"]
        self.assertEqual(self.desk.save_settings(s), [])
        self.desk.set_provider_state("claude", cool_until=now() + 600, reason="taking a rest")
        self.assertEqual(sorted(s["lanes"])[0], "0")
        self.assertEqual(provider_problem(self.desk, s, "verifier"), "")
        tid = self.desk.new_task("Unassigned work")
        reason = waiting_reason(self.desk, s, self.desk.meta(tid), set())
        self.assertIn("lane a has no provider ready (claude: resting", reason)
        self.assertNotIn("lane 0", reason)

    def test_verify_lane_set_refuses_repo(self):
        self.add_verify_lane()
        before = self.desk.settings_path.read_bytes()
        errors = io.StringIO()
        with contextlib.redirect_stderr(errors), self.assertRaises(SystemExit) as e:
            self.hansa("lane", "set", "a", "repo", str(self.repo))
        self.assertEqual(e.exception.code, 2)
        self.assertIn("argument field: invalid choice: 'repo'", errors.getvalue())
        self.assertEqual(self.desk.settings_path.read_bytes(), before)

    def test_verify_lane_settings_refuse_invalid_targets_atomically(self):
        self.hansa("lane", "add", "v1", "--like", "a")
        self.hansa("lane", "add", "b", "--like", "a")
        self.add_verify_lane("v2")
        self.merge_lane_for_checks()
        other = self.tmp / "other"
        shutil.copytree(self.repo, other)
        self.hansa("lane", "add", "c", "--repo", str(other))
        before = self.desk.settings_path.read_bytes()
        for target, reason in (("c", "another repository"), ("v1", "itself"), ("m", "merge lane"),
                               ("v2", "verify lane"), ("missing", "no lane missing")):
            with self.subTest(target=target), self.assertRaises(SystemExit) as e:
                self.hansa("lane", "set", "v1", "verify_for", target)
            self.assertIn("lane v1:", str(e.exception))
            self.assertIn(reason, str(e.exception))
            self.assertEqual(self.desk.settings_path.read_bytes(), before)
        for bad in ("a", [1], ["a", {}], None):
            s = self.desk.settings()
            s["lanes"]["v1"]["verify_for"] = bad
            self.assertIn("lane v1: verify_for must be a list of lane names", self.desk.save_settings(s))
            self.assertEqual(self.desk.settings_path.read_bytes(), before)

    def test_verify_lane_settings_recheck_relationships_on_every_save(self):
        self.add_verify_lane()
        other = self.tmp / "other"
        shutil.copytree(self.repo, other)
        before = self.desk.settings_path.read_bytes()
        for args, reason in ((("a", "merge_lane", "true"), "merge lane"),
                             (("a", "verify_for", "v1"), "verify lane"),
                             (("v1", "merge_lane", "true"), "merge lane cannot be a verify lane")):
            with self.subTest(args=args), self.assertRaises(SystemExit) as e:
                self.hansa("lane", "set", *args)
            self.assertIn("lane v1:", str(e.exception))
            self.assertIn(reason, str(e.exception))
            self.assertEqual(self.desk.settings_path.read_bytes(), before)
        s = self.desk.settings()
        s["lanes"]["a"]["repo"] = str(other)
        self.assertIn("lane v1: verify_for cannot name lane a: it is on another repository",
                      self.desk.save_settings(s))
        self.assertEqual(self.desk.settings_path.read_bytes(), before)
        s = self.desk.settings()
        del s["lanes"]["a"]
        self.assertTrue(any("lane v1:" in p and "no lane a" in p for p in self.desk.save_settings(s)))
        self.assertEqual(self.desk.settings_path.read_bytes(), before)

    def test_verify_lane_cannot_be_merge_lane_or_hold_ordinary_work(self):
        self.merge_lane_for_checks()
        before = self.desk.settings_path.read_bytes()
        with self.assertRaises(SystemExit) as e:
            self.hansa("lane", "set", "m", "verify_for", "a")
        self.assertIn("lane m: a merge lane cannot be a verify lane", str(e.exception))
        self.assertEqual(self.desk.settings_path.read_bytes(), before)
        self.hansa("lane", "add", "v1", "--like", "a")
        tid = self.desk.new_task("ordinary work", lane="v1")
        before = self.desk.settings_path.read_bytes()
        for state in ("queued", "running"):
            self.desk.update(tid, state=state)
            with self.subTest(state=state), self.assertRaises(SystemExit) as e:
                self.hansa("lane", "set", "v1", "verify_for", "a")
            self.assertIn(f"lane v1: cannot become a verify lane while {tid} is queued or running there",
                          str(e.exception))
            self.assertEqual(self.desk.settings_path.read_bytes(), before)
        self.desk.update(tid, state="done")
        vid = self.desk.new_task("verification", lane="v1", kind="verify")
        for state in ("queued", "running"):
            self.desk.update(vid, state=state)
            self.hansa("lane", "set", "v1", "verify_for", "a")
            self.hansa("lane", "set", "v1", "verify_for", "none")

    def test_verify_lane_remove_cleans_every_list_and_unset_restores_work(self):
        self.hansa("lane", "add", "b", "--like", "a")
        self.add_verify_lane("v1", "a", "b")
        self.add_verify_lane("v2")
        out = self.hansa("lane", "remove", "a")
        for lane in ("v1", "v2"):
            self.assertNotIn("a", self.desk.settings()["lanes"][lane].get("verify_for", []))
            self.assertIn(f"lane a removed from lane {lane}'s verify_for", out)
        self.assertEqual(self.desk.settings()["lanes"]["v1"]["verify_for"], ["b"])
        self.assertNotIn("verify_for", self.desk.settings()["lanes"]["v2"])
        self.hansa("add", "work", "--lane", "v2")
        self.hansa("lane", "set", "v1", "verify_for", "none")
        self.assertNotIn("verify_for", self.desk.settings()["lanes"]["v1"])
        self.hansa("add", "work", "--lane", "v1")

