    def test_waiting_reason_says_a_stuck_server_is_busy_or_stuck(self):
        from hansa import run
        tid = self.desk.new_task("Anything")
        held = cli.hold_server_lock(self.desk)
        self.addCleanup(held.close)
        for quiet, said in ((0, "starts when `hansa serve` next looks (within seconds)"),
                            (run.ROUND_QUIET + 5, "starts when `hansa serve` next looks (within seconds)"),
                            (run.STUCK_AFTER + 60, "but `hansa serve` is busy or stuck: no round finished for 6 minutes")):
            self.round_at(quiet)
            why = waiting_reason(self.desk, self.desk.settings(), self.desk.meta(tid), set())
            self.assertIn(said, why)
            self.assertEqual("within seconds" in why, quiet < run.STUCK_AFTER, why)
        self.assertIn("busy or stuck", why)
        held.close()
        why = waiting_reason(self.desk, self.desk.settings(), self.desk.meta(tid), set())
        self.assertIn("but `hansa serve` is not running", why)

    def test_status_reads_the_tasks_once_and_what_the_queued_ones_wait_on_once(self):
        from hansa import run
        held = cli.hold_server_lock(self.desk)
        self.addCleanup(held.close)
        self.round_at(0)
        ids = [self.desk.new_task(f"Task {i}") for i in range(4)]
        alone = {t: waiting_reason(self.desk, self.desk.settings(), self.desk.meta(t), set()) for t in ids}
        reads = {"tasks": 0, "paused": 0, "server": 0}
        tasks, paused, server = Desk.tasks, Desk.paused, run.server_state

        def count(name, fn):
            def f(*a, **k):
                reads[name] += 1
                return fn(*a, **k)
            return f
        with unittest.mock.patch.object(Desk, "tasks", count("tasks", tasks)), \
                unittest.mock.patch.object(Desk, "paused", count("paused", paused)), \
                unittest.mock.patch("hansa.run.server_state", count("server", server)), \
                unittest.mock.patch("hansa.views.server_state", count("server", server)):
            st = views.status(self.desk)
        self.assertEqual(reads, {"tasks": 1, "paused": 2, "server": 1})  # paused: the status's own, and the waiting lines'
        self.assertEqual({m["id"]: m["waiting"] for m in st["queued"]}, alone)  # as each says it alone

    def test_a_release_without_asking_says_what_its_waiting_text_says_when_the_server_does_not_look(self):
        from hansa import release, run
        self.with_targets(test=f"touch {self.tmp / 'installed.txt'}")
        self.tick_targets("test")
        held = cli.hold_server_lock(self.desk)
        self.addCleanup(held.close)
        for n, quiet, said in ((1, 0, f"serve runs the command in {self.repo.resolve()} within seconds. "),
                               (2, run.STUCK_AFTER + 60, "serve runs the command in "
                                f"{self.repo.resolve()} once it gets through its rounds; `hansa serve` is busy or "
                                "stuck: no round finished for 6 minutes. ")):
            self.round_at(quiet)
            out = self.hansa("release", "a", "test")
            self.assertIn(said, out)
            self.assertEqual("within seconds" in out, not quiet, out)
            release.change(self.desk, n, lambda x: {"state": "stopped"})  # ended: the next may be asked
        held.close()
        out = self.hansa("release", "a", "test")
        self.assertIn("once it gets through its rounds; `hansa serve` is not running. ", out)
        self.assertIn(release.waits_text(self.desk, self.desk.settings(), release.get(self.desk, 3)), out)
        self.assertNotIn("within seconds", out)

