    def test_an_allowlist_change_during_a_release_scan_makes_it_scan_again(self):
        from hansa import release
        self.with_release("true")
        self.commit_in_repo("README.md", "jane@realmail.hansa\n")
        self.assertEqual(self.page_save(lambda s: s.update(release_mailboxes=True)), {"ok": True, "problems": []})
        real_scan = release.forbidden_in
        calls = []

        def changed_during_scan(*args, **kw):
            found = real_scan(*args, **kw)
            calls.append(found)
            if len(calls) == 1:
                self.assertEqual(self.page_save(lambda s: s.update(release_mailbox_allow=["jane@realmail.hansa"])),
                                 {"ok": True, "problems": []})
            return found
        with unittest.mock.patch("hansa.release.forbidden_in", changed_during_scan):
            self.hansa("release", "a")
        self.assertEqual(len(calls), 2)
        self.assertEqual(calls[0][0][0]["word"], "jane@realmail.hansa")
        self.assertEqual(calls[1][0], [])
        self.assertEqual(release.get(self.desk, 1)["state"], "waiting")

    def test_a_listed_lane_goes_out_without_asking_only_while_it_is_what_the_principal_listed(self):
        from hansa import release
        from hansa.desk import public_settings
        out = self.tmp / "ran.txt"
        self.with_release(f"touch {out}")
        self.assertEqual(self.page_save(lambda s: s.update(releases_without_asking=["a"])), {"ok": True, "problems": []})
        [entry] = self.desk.settings()["releases_without_asking"]
        self.assertEqual(entry, {"lane": "a", "target": "default", "repo": str(self.repo.resolve()), "base": "main",
                                 "command": f"touch {out}", "after": ""})
        self.assertEqual(public_settings(self.desk)["release_unmatched"], [])

        def asked():
            self.hansa("release", "a")
            return release.releases(self.desk)[-1]

        def take_back_in():  # the page saves the list again
            self.assertEqual(self.page_save(lambda s: s.update(releases_without_asking=["a"])),
                             {"ok": True, "problems": []})
            self.assertEqual(public_settings(self.desk)["release_unmatched"], [])
            r = asked()
            self.assertEqual(r["state"], "approved")
            release.change(self.desk, r["id"], lambda x: {"state": "void", "void": "not run in this test"})

        # its base branch changed: it waits for the yes, and the page shows the entry as no longer matching
        sh("git", "branch", "dev", cwd=self.repo)
        self.hansa("lane", "set", "a", "base", "dev")
        self.assertEqual(asked()["state"], "waiting")
        [u] = public_settings(self.desk)["release_unmatched"]
        self.assertEqual((u["lane"], u["why"]), ("a", "its base branch changed since the list was saved"))
        self.assertIn("基础分支", u["why_zh"])
        self.assertIn("releases wait for the yes until the principal takes it back in on the page (its button for "
                      "that, or unticking and ticking it again, then Save; a plain Save keeps the old entry)",
                      self.hansa("explain", "lane", "a"))
        self.assertEqual(self.desk.settings()["releases_without_asking"], [entry])  # hansa leaves the list as it is
        take_back_in()
        # its release command changed
        self.hansa("lane", "target", "a", "default", f"touch {out}; true")
        self.assertEqual(asked()["state"], "waiting")
        self.assertIn("release command changed", public_settings(self.desk)["release_unmatched"][0]["why"])
        take_back_in()
        # removed and added again, under the same name, on another repository: the same base branch (dev, as it
        # was taken back in) and command, so only the repository differs
        other = self.tmp / "other-repo"
        other.mkdir()
        sh("git", "init", "-q", "-b", "dev", cwd=other)
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "init", cwd=other)
        self.hansa("lane", "remove", "a")
        self.hansa("lane", "add", "a", "--repo", str(other), "--base", "dev")
        self.hansa("lane", "target", "a", "default", f"touch {out}; true")
        [entry] = self.desk.settings()["releases_without_asking"]
        self.assertEqual((entry["base"], entry["command"]), ("dev", f"touch {out}; true"))
        r = asked()
        self.assertEqual((r["state"], r["repo"]), ("waiting", str(other.resolve())))
        self.assertEqual(public_settings(self.desk)["release_unmatched"][0]["why"],
                         "its repository changed since the list was saved")
        # one listed and asked, then changed before it ran: back to waiting for the yes
        take_back_in()
        rid = asked()["id"]
        self.assertEqual(release.get(self.desk, rid)["state"], "approved")
        self.hansa("lane", "target", "a", "default", f"touch {out}")
        Dispatcher(self.desk).tick()
        self.assertEqual(release.get(self.desk, rid)["state"], "waiting")
        self.assertFalse(out.exists())

    def test_while_the_desk_is_paused_only_a_release_the_principal_said_yes_to_runs(self):
        from hansa import release
        out = self.tmp / "ran.txt"
        self.with_release(f"echo x >> {out}")
        self.assertEqual(self.page_save(lambda s: s.update(releases_without_asking=["a"])), {"ok": True, "problems": []})
        self.hansa("pause", "a quiet day")
        told = self.hansa("release", "a")
        self.assertIn("the desk is paused (a quiet day)", told)
        self.assertIn("waits until the desk is resumed", told)
        d = Dispatcher(self.desk)
        for _ in range(3):
            d.tick()
        r = release.get(self.desk, 1)
        self.assertEqual(r["state"], "approved")
        self.assertFalse(out.exists())
        self.assertIn("waits until the desk is resumed", self.hansa("release"))
        [row] = views.status(self.desk)["releases"]
        self.assertIn("waits until the desk is resumed", row["what"])
        self.assertIn("等桌面恢复", row["what_zh"])
        # one the principal said yes to runs while paused
        self.assertEqual(self.page_save(lambda s: s.update(releases_without_asking=[])), {"ok": True, "problems": []})
        d.tick()  # off the list: #1 waits for the yes now
        self.assertEqual(release.get(self.desk, 1)["state"], "waiting")
        self.assertEqual(release.answer(self.desk, 1, True, "", r["commit"], r["command"]), {"ok": True})
        self.assertEqual(self.settle_release(d, 1)["state"], "done")
        self.assertEqual(out.read_text(), "x\n")
        # and a listed lane's release runs once the desk is resumed
        self.assertEqual(self.page_save(lambda s: s.update(releases_without_asking=["a"])), {"ok": True, "problems": []})
        self.commit_in_repo("b.txt", "b\n")
        self.hansa("release", "a")
        d.tick()
        self.assertEqual(release.get(self.desk, 2)["state"], "approved")
        self.hansa("resume")
        self.assertEqual(self.settle_release(d, 2)["state"], "done")
        self.assertEqual(out.read_text(), "x\nx\n")

    # -- free space: the floor, and what old tasks kept (hansa/disk.py) ----------------------------------------------
    def memory_reading(self, available=8, total=16):
        """Available and total GB, set by the test instead of the host's memory pressure."""
        self.memory_available, self.memory_total = available * 10 ** 9, total * 10 ** 9
        reader = unittest.mock.patch("hansa.memory.measure", lambda: {
            "available": self.memory_available, "total": self.memory_total})
        reader.start()
        self.addCleanup(reader.stop)

    def test_under_the_memory_floor_nothing_starts_and_running_work_goes_on(self):
        from hansa import alert
        self.memory_reading()
        s = self.desk.settings()
        s["lanes"]["b"] = json.loads(json.dumps(s["lanes"]["a"]))
        s["lanes"]["a"]["check"] = "test -f README.md"
        s["concurrency"] = 2
        self.assertEqual(self.desk.save_settings(s), [])
        self.assertTrue(self.page_save(lambda s: s.update(alert={"command": "cat > /dev/null"}))["ok"])
        d = Dispatcher(self.desk)
        running = self.desk.new_task("Add hello.txt", lane="a")
        d.tick()
        self.assertEqual(self.desk.meta(running)["state"], "running")
        self.memory_available = 10 ** 9
        waiting = self.desk.new_task("Add more.txt", lane="b")
        d.tick()
        self.assertEqual(self.desk.meta(waiting)["state"], "queued")
        [low] = self.events("memory_low")
        self.assertEqual(low["floor"], 2)
        said = self.hansa("status")
        self.assertIn("memory: 1.0 GB available · floor 2 GB (hansa memory-floor)", said)
        self.assertIn("MEMORY LOW: 1.0 GB available (floor 2 GB)", said)
        self.assertIn("until 3.0 GB is available; what runs goes on", said)
        self.assertIn("waiting: hansa serve starts nothing new while available memory is under its floor", said)
        self.assertIn("now: MEMORY LOW", self.hansa("explain", "server"))
        self.assertEqual(self.settle(d, running)["state"], "done")
        self.assertEqual(self.desk.meta(running)["check"]["ok"], True)
        item = notify._item(self.desk, low)
        self.assertEqual(item[0], ("memory",))
        self.assertTrue(item[3])
        self.assertIn("available memory is under", item[1])
        alert.from_event(self.desk, "memory_low", low)
        self.assertEqual(alert.queued(self.desk), [])

