    def test_a_look_that_fails_after_a_low_reading_leaves_no_stale_warning(self):
        from hansa import disk
        locked = self.unreadable_lane_b()
        locked.chmod(0o700)
        self.free_at = {locked: 2 * 10 ** 9}  # only lane b's repository's place is low
        d = Dispatcher(self.desk)
        d.tick()
        self.assertIn("lane b's repository", self.hansa("status").split("DISK LOW: ")[1].splitlines()[0])
        # its folder can no longer be read: the place left out, the rest over the floor, so hansa serve starts again
        locked.chmod(0)
        tid = self.desk.new_task("Add hello.txt", lane="a")
        d.tick()
        self.assertNotEqual(self.desk.meta(tid)["state"], "queued")
        said = self.hansa("status")
        self.assertNotIn("DISK LOW", said)
        self.assertIn("hansa serve cannot look at lane b's repository", said)
        self.assertEqual(self.settle(d, tid)["state"], "done")
        self.assertEqual(len(self.events("disk_ok")), 1)
        # a look that fails as a whole after a low reading: nothing is held, and status says what was last known
        locked.chmod(0o700)
        self.free_at = {}
        self.free = 2 * 10 ** 9
        d.tick()
        self.assertIn("DISK LOW", self.hansa("status"))
        with unittest.mock.patch("hansa.disk.measure", side_effect=PermissionError(13, "Permission denied")):
            tid = self.desk.new_task("Add more.txt", lane="a")
            for _ in range(3):
                d.tick()
            self.assertNotEqual(self.desk.meta(tid)["state"], "queued")
            self.assertEqual(disk.held(self.desk), [])
            said = self.hansa("status")
            self.assertNotIn("DISK LOW", said)
            self.assertRegex(said, r"disk: hansa serve could not look at free space since \d\d:\d\d \(PermissionError: "
                                   r"\[Errno 13\] Permission denied\), so it holds nothing back until it can; last "
                                   r"measured \d\d:\d\d: .*has 2\.0 GB free, under the floor then")
            self.assertNotIn("waiting: hansa serve starts nothing new", said)
            self.assertIn("could not look at free space", self.hansa("explain", "server"))
            self.assertEqual(self.settle(d, tid)["state"], "done")
        self.assertEqual([e.get("error") for e in self.events("disk_look_failed")][-1:],
                         ["PermissionError: [Errno 13] Permission denied"])  # once, not each round
        self.assertEqual(sum(1 for e in self.events("disk_look_failed") if e.get("error")), 1)
        self.free = 500 * 10 ** 9
        d.tick()
        self.assertEqual(sum(1 for e in self.events("disk_look_ok") if e.get("error")), 1)
        self.assertNotIn("could not look at", self.hansa("status"))

    def test_the_disk_record_is_written_only_when_what_its_readers_use_changes(self):
        from hansa import disk
        d = Dispatcher(self.desk)
        at = time.mktime((2026, 1, 5, 10, 0, 0, 0, 0, -1))  # a round's look, by the clock
        with unittest.mock.patch("hansa.disk.now", lambda: at):
            d.tick()
            self.assertEqual(set(disk.record(self.desk)), {"measured", "floor", "low", "failed"})
            with unittest.mock.patch("hansa.disk.write_json", wraps=disk.write_json) as written, \
                    unittest.mock.patch("hansa.disk._mount", wraps=disk._mount) as mounts:
                at += 30  # the same minute, the same free space: nothing to write, nor any mount to look up again
                d.tick()
                self.assertEqual((written.call_count, mounts.call_count), (0, 0))
                at += 30  # the minute status shows as when it last measured
                d.tick()
                self.assertEqual(written.call_count, 1)
                self.free = 2 * 10 ** 9  # under the floor
                d.tick()
                self.assertEqual(written.call_count, 2)
        self.assertEqual(disk.record(self.desk)["measured"], at)
        self.assertTrue(disk.held(self.desk))

    def test_serve_trims_the_logs_of_tasks_that_ended_over_30_days_ago_and_keeps_the_rest_whole(self):
        from hansa import disk
        day = 86400
        big = "".join(f"build line {i}\n" for i in range(60000)).encode()  # some 900 KB
        self.assertGreater(len(big), 3 * disk.TRIM_KEEP)
        at = time.time()
        tids = {}
        for name, fields in (("old", {"state": "merged", "merged": at - 31 * day, "setup_exit": 1}),
                             ("cancelled", {"state": "cancelled", "finished": at - 40 * day}),
                             ("recent", {"state": "failed", "finished": at - 29 * day}),
                             ("review", {"state": "done", "finished": at - 29 * day})):
            tid = self.desk.new_task(f"Task {name}")
            self.desk.update(tid, **fields)
            folder = self.desk.tasks_dir / tid
            for f in ("check.log", "setup.log", "run.err", "merge-check.log", "result.md", "run.json"):
                (folder / f).write_bytes(big)
            tids[name] = tid
        # replaced: ended when its follow-up was made
        old_follow = self.desk.new_task("Follow-up")
        self.desk.update(old_follow, created=at - 35 * day)
        replaced = self.desk.new_task("Replaced")
        self.desk.update(replaced, state="replaced", replaced_by=old_follow, created=at - 36 * day)
        (self.desk.tasks_dir / replaced / "check.log").write_bytes(big)
        events = self.desk.events_path.read_bytes()
        task_md = (self.desk.tasks_dir / tids["old"] / "task.md").read_bytes()
        d = Dispatcher(self.desk)
        d.tick()  # its first round trims, then once a day
        trimmed = {tids["old"], tids["cancelled"], replaced}
        for name, tid in tids.items():
            folder = self.desk.tasks_dir / tid
            for f in ("check.log", "setup.log", "run.err", "merge-check.log"):
                data = (folder / f).read_bytes()
                if tid not in trimmed:
                    self.assertEqual(data, big, (name, f))
                    continue
                head, rest = data.split(b"\n", 1)
                self.assertRegex(head.decode(), r"^\[hansa trimmed this log on \d{4}-\d\d-\d\d \d\d:\d\d: it was "
                                                 rf"{len(big):,} bytes; its last [\d,]+ bytes follow\]$")
                self.assertLessEqual(len(rest), disk.TRIM_KEEP)
                self.assertGreater(len(rest), disk.TRIM_KEEP - 1024)
                self.assertTrue(big.endswith(rest))
                self.assertTrue(rest.startswith(b"build line "))  # from the start of a line
            for f in ("result.md", "run.json"):  # the report and the result stay whole
                self.assertEqual((folder / f).read_bytes(), big, (name, f))
        self.assertEqual((self.desk.tasks_dir / tids["old"] / "task.md").read_bytes(), task_md)
        self.assertTrue((self.desk.tasks_dir / replaced / "check.log").read_bytes().startswith(b"[hansa trimmed"))
        self.assertTrue(self.desk.events_path.read_bytes().startswith(events))  # the event log: not touched
        [e] = self.events("logs_trimmed")
        self.assertEqual(sorted(e["tasks"]), sorted(trimmed))
        self.assertEqual(sorted(self.desk.meta(tids["old"])["trimmed"]),
                         ["check.log", "merge-check.log", "run.err", "setup.log"])
        shown = self.hansa("show", tids["old"])
        self.assertIn("logs trimmed (merged passed: first 32 + last 256 KB; other ended/done over "
                      "30 days: last 256 KB): check.log on ", shown)
        self.assertNotIn("logs trimmed", self.hansa("show", tids["recent"]))
        # trimmed once: the next day's trim finds nothing more to cut
        self.assertEqual(disk.trim(self.desk, at + day / 2), [])
        d.tick()
        self.assertEqual(len(self.events("logs_trimmed")), 1)

    def test_daily_trim_keeps_the_head_and_tail_of_merged_tasks_passed_logs_at_once(self):
        from hansa import disk
        at = time.time()
        tid = self.desk.new_task("Merged build", state="merged", merged=at - 60, setup_exit=0,
                                 check={"ok": True}, merge_check_result={"ok": True})
        folder = self.desk.tasks_dir / tid
        big = b"build output\n" * 60000
        passed = ("setup.log", "check.log", "merge-check.log", "merge-setup.log")
        for name in (*disk.TRIMMED, "result.md", "run.json", "other.log"):
            (folder / name).write_bytes(big)
        before = self.desk.meta(tid)
        events = self.desk.events_path.read_bytes()
        task = (folder / "task.md").read_bytes()
        Dispatcher(self.desk).tick()  # the same daily trim used by serve
        for name in (*disk.TRIMMED, "result.md", "run.json", "other.log"):
            data = (folder / name).read_bytes()
            if name not in passed:
                self.assertEqual(data, big, name)
                continue
            head, marker, rest = data.partition(b"[hansa trimmed this log on ")
            cut, tail = rest.split(b"\n", 1)
            self.assertEqual(head, big[:big.rfind(b"\n", 0, disk.TRIM_HEAD) + 1], name)
            expected_tail = big[-disk.TRIM_KEEP:]
            self.assertEqual(tail, expected_tail[expected_tail.find(b"\n") + 1:], name)
            self.assertRegex((marker + cut).decode(), rf"^\[hansa trimmed this log on .*: cut "
                            rf"{len(big) - len(head) - len(tail):,} bytes\]$")
        after = self.desk.meta(tid)
        self.assertEqual(after.pop("trimmed").keys(), set(passed))
        self.assertEqual(after, before)  # only the trim record changes
        self.assertEqual((folder / "task.md").read_bytes(), task)
        self.assertTrue(self.desk.events_path.read_bytes().startswith(events))
        [e] = self.events("logs_trimmed")
        self.assertEqual((e["tasks"], e["files"]), ([tid], len(passed)))

    def test_daily_trim_leaves_a_1_kb_margin_so_small_cuts_cannot_grow_logs(self):
        from hansa import disk
        at = time.time()
        tid = self.desk.new_task("Merged build", state="merged", merged=at - 60, check={"ok": True})
        log = self.desk.tasks_dir / tid / "check.log"
        for extra in (-1, 0, 1, 1023, 1024, 1025):
            with self.subTest(extra=extra):
                size = disk.TRIM_HEAD + disk.TRIM_KEEP + extra
                data = b"x" * size
                log.write_bytes(data)
                cut = disk.trim(self.desk, at)
                if extra <= 1024:
                    self.assertEqual(cut, [])
                    self.assertEqual(log.read_bytes(), data)
                else:
                    self.assertEqual(cut, [(tid, "check.log", size)])
                    self.assertIn(b": cut 1,025 bytes]\n", log.read_bytes())
                    self.assertLess(log.stat().st_size, size)

    def test_daily_trim_preserves_utf8_lines_and_scrubs_a_key_saved_after_the_cut(self):
        from hansa import disk
        at = time.time()
        key = "sk-trim-later-123456"
        for width, count in ((31, 12000), (1400, 300)):
            with self.subTest(line_width=width):
                tid = self.desk.new_task("Merged build", state="merged", merged=at - 60, check={"ok": True})
                log = self.desk.tasks_dir / tid / "check.log"
                big = (key + "\n" + ("界" * width + "\n") * count + key + "\n").encode()
                # Both raw offsets split a multi-byte character; long lines also exercise the fallback.
                self.assertEqual(big[disk.TRIM_HEAD] & 0xC0, 0x80)
                self.assertEqual(big[-disk.TRIM_KEEP] & 0xC0, 0x80)
                log.write_bytes(big)
                self.assertEqual(disk.trim(self.desk, at), [(tid, "check.log", len(big))])
                data = log.read_bytes()
                data.decode("utf-8")  # strict decoding, as Desk.scrub uses
                head, _, rest = data.partition(b"[hansa trimmed this log on ")
                cut, tail = rest.split(b"\n", 1)
                if width == 31:
                    kept = head
                    self.assertEqual(head, big[:big.rfind(b"\n", 0, disk.TRIM_HEAD) + 1])
                    expected_tail = big[-disk.TRIM_KEEP:]
                    self.assertEqual(tail, expected_tail[expected_tail.find(b"\n") + 1:])
                else:
                    kept = head[:-1]  # the separator's added newline
                    self.assertGreaterEqual(len(kept), disk.TRIM_HEAD - 3)
                    self.assertGreaterEqual(len(tail), disk.TRIM_KEEP - 3)
                    self.assertTrue(big.startswith(kept))
                    self.assertTrue(big.endswith(tail))
                self.assertIn(f": cut {len(big) - len(kept) - len(tail):,} bytes]".encode(), cut)
                self.assertEqual(data.count(key.encode()), 2)  # a key in each retained part
                self.assertEqual(disk.trim(self.desk, at + 31 * 86400), [])
                self.assertIsNone(disk._trim_one(log, at + 31 * 86400))  # also safe from a tail-only cut
                self.assertEqual(log.read_bytes(), data)
                self.desk.write_key("mimo", key)
                scrubbed = log.read_text(encoding="utf-8")
                self.assertNotIn(key, scrubbed)
                self.assertEqual(scrubbed.count("[key of mimo]"), 2)

