    def test_trimmed_done_logs_are_not_read_by_verify_merge_retry_or_show_report(self):
        from hansa import disk
        s = self.desk.settings()
        s["lanes"]["a"].update(setup="true", check="true", env={"FAKE_VERDICT": "holds"})
        self.assertEqual(self.desk.save_settings(s), [])
        d = Dispatcher(self.desk)
        m = self.settle(d, self.desk.new_task("Add hello.txt"))
        self.assertEqual((m["state"], m["check"]["ok"]), ("done", True))
        tid, at = m["id"], time.time()
        folder = self.desk.tasks_dir / tid
        report = (folder / "result.md").read_text().strip()
        self.desk.update(tid, finished=at - 31 * 86400)
        for name in disk.TRIMMED:
            (folder / name).write_bytes(b"build output\n" * 60000)
        self.assertEqual(len(disk.trim(self.desk, at)), len(disk.TRIMMED))
        opened = Path.open

        def no_log_reads(path, mode="r", *args, **kwargs):
            if path.parent == folder and path.name in disk.TRIMMED and ("r" in mode or "+" in mode):
                self.fail(f"a decision read a trimmed log: {path.name}")
            return opened(path, mode, *args, **kwargs)

        with unittest.mock.patch.object(Path, "open", no_log_reads):
            self.assertEqual(self.hansa("show", tid, "--report").strip(), report)
            self.hansa("verify", tid)
            vid = self.desk.meta(tid)["verify"]
            self.assertEqual(self.settle(d, vid)["verdict"], "holds")
            self.hansa("merge", tid)
            self.assertEqual(self.desk.meta(tid)["state"], "merged")
            follow = self.hansa("retry", tid, "Continue the work").split()[0]
            self.assertEqual(self.desk.meta(follow)["state"], "queued")
            self.assertIn(report, (self.desk.tasks_dir / follow / "task.md").read_text())

    def test_a_forbidden_word_in_an_authors_email_or_a_committers_name_refuses_a_release(self):
        from hansa import release
        self.with_release("true")
        (self.repo / "x.txt").write_text("clean\n")
        sh("git", "add", "x.txt", cwd=self.repo)
        who = {"GIT_AUTHOR_NAME": "Ada", "GIT_AUTHOR_EMAIL": "ada@falcon.example", "GIT_COMMITTER_NAME": "Osprey Bot",
               "GIT_COMMITTER_EMAIL": "bot@example.org"}
        subprocess.run(["git", "commit", "-q", "-m", "Clean"], cwd=self.repo, check=True, env={**os.environ, **who})
        sha = self.git_out("rev-parse", "HEAD")
        self.commit_in_repo("y.txt", "clean too\n")  # by t <t@t>: nothing to find
        self.assertEqual(self.page_save(lambda s: s.update(release_forbidden=["FALCON", "osprey"])),
                         {"ok": True, "problems": []})
        said = self.refused("release", "a")
        self.assertIn(f"{sha[:10]} author: Ada <ada@falcon.example>", said)
        self.assertIn(f"{sha[:10]} committer: Osprey Bot <bot@example.org>", said)
        self.assertEqual(sorted((h["commit"], h["where"]) for h in release.get(self.desk, 1)["hits"]),
                         [(sha, "author"), (sha, "committer")])

    def test_a_release_command_set_with_a_forbidden_word_is_said_at_once_and_kept(self):
        self.assertEqual(self.page_save(lambda s: s.update(release_forbidden=["maplebox"])), {"ok": True, "problems": []})
        out = self.hansa("lane", "target", "a", "default", "scp target/app.jar /Users/MapleBox/deploy/")
        self.assertIn("Warning: lane a's release target default holds \"maplebox\"", out)
        self.assertIn("scp target/app.jar /Users/MapleBox/deploy/", out)
        self.assertEqual(self.desk.settings()["lanes"]["a"]["targets"]["default"]["command"], "scp target/app.jar /Users/MapleBox/deploy/")
        self.assertNotIn("Warning", self.hansa("lane", "target", "a", "default", "none"))
        self.assertNotIn("Warning", self.hansa("lane", "target", "a", "push", "git push origin main"))
        out = self.hansa("lane", "target", "a", "test", "./install.sh /home/maplebox/test")
        self.assertIn("Warning: lane a's release target test holds \"maplebox\"", out)
        self.assertIn("./install.sh /home/maplebox/test", out)
        self.assertNotIn("target push", out)
        self.assertEqual(self.desk.settings()["lanes"]["a"]["targets"]["test"]["command"], "./install.sh /home/maplebox/test")
        out = self.hansa("lane", "target", "a", "test", "--minutes", "30")  # changed otherwise: still said
        self.assertIn("release target test holds \"maplebox\"", out)
        out = self.hansa("lane", "add", "b", "--like", "a")
        self.assertIn("Warning: lane b's release target test holds \"maplebox\"", out)
        self.assertIn("test", self.desk.settings()["lanes"]["b"]["targets"])
        said = self.refused("release", "a", "test")  # and refused at release time, as before
        self.assertIn("release command: ./install.sh /home/maplebox/test", said)

    def test_explain_lane_reports_check_times_repetition_and_release_file_matches(self):
        rows = [
            (1, [60] * 5 + [100] * 3, "check"),
            (2, [60] * 5 + [70] * 3, "check"),
            (3, [60], "check"),
            (4, [60, 120], "check"),
            (5, [60] * 5 + [100] * 3, "merge_check_result"),
            (6, [], "check"),
            (7, [], "check"),
            (8, [], "check"),
            (9, [], "check"),
            (10, [], "check"),
            (11, [], "check"),
            (12, [60, 120], "merge_check_result"),
            (13, [], "check"),
            (14, [], "check"),
        ]
        fixed_now = time.time()
        for row, seconds, field in rows:
            with self.subTest(row=row):
                desk = init_desk(self.tmp / f"explain-{row}", str(self.repo), "a")
                s = desk.settings()
                ln = s["lanes"]["a"]
                ln.update(check="make lint", merge_check="make test-all")
                if row in (5, 9, 10, 12):
                    s["lanes"]["m"] = {**ln, "merge_lane": True}
                if row == 9:
                    ln["merge_check"] = "make lint && make all"
                    s["lanes"]["m"]["merge_check"] = "make test"
                if row == 10:
                    ln.pop("merge_check")
                    s["lanes"]["m"]["merge_check"] = " make   lint && make all "
                if row == 12:
                    s["lanes"]["b"] = dict(ln)
                    s["lanes"]["m"].pop("check")
                if row == 13:
                    ln.pop("check")
                if row == 6:
                    ln["merge_check"] = " make   lint  && make test-all "
                if row == 8:
                    ln["release_files"] = ["pom.xml", "tools/**"]  # count order, not settings order
                if row in (11, 14):
                    ln["release_files"] = ["tools/**"]
                self.assertEqual(desk.save_settings(s), [])

                def record(duration, index, **changes):
                    ended = fixed_now - 10000 + index * 200
                    result = {"command": "make lint" if field == "check" else "make test-all",
                              "ok": index % 2 == 0, "exit": 0 if index % 2 == 0 else 1,
                              "note": "", "seconds": duration}
                    if field == "merge_check_result":
                        result.update(at=ended, lane="m" if index % 2 else "a")
                    result.update(changes)
                    if row == 12:
                        result["lane"] = "m"
                    tid = desk.new_task(f"Run {index}", lane="b" if row == 12 and index else "a")
                    desk.update(tid, state="done", check_started=ended - duration, **{field: result})
                    if row == 4:
                        desk.update(tid, merge_check_result={**result, "at": ended})

                # Record out of chronological order so task ids cannot determine newest first.
                for i in reversed(range(len(seconds))):
                    record(seconds[i], i)
                if row == 4:
                    for i, change in enumerate((
                        {"ok": False, "exit": 143, "note": "stopped on request"},
                        {"ok": False, "exit": 143, "note": "stopped at the lane's time ceiling"},
                        {"ok": False, "exit": None, "note": "cancelled"},
                        {"ok": None, "exit": None, "could_not_run": True, "note": "could not run: no srt"},
                        {"ok": False, "exit": None, "note": "the check was interrupted"},
                        {"ok": False, "exit": 1, "note": "the lane's setup failed (exit 1), so the check did not run"},
                    ), 10):
                        record(999, i, **change)
                if row in (1, 4, 5):
                    # Other lanes and verifications do not supply this lane's task checks.
                    other = desk.new_task("Other lane", lane="b")
                    verify = desk.new_task("Verification", lane="a", kind="verify")
                    for tid in (other, verify):
                        desk.update(tid, check_started=fixed_now, **{field: {
                            "ok": True, "exit": 0, "seconds": 999, "at": fixed_now}})
                if row == 8:
                    for i, (days, files, state, lane) in enumerate([
                        (1, ["tools/a.sh", "tools/b.sh"], "merged", "a"),
                        (2, ["tools/nested/c.sh"], "merged", "a"),
                        (3, ["tools/d.sh"], "merged", "a"),
                        (4, ["tools/e.sh"], "merged", "a"),
                        (5, ["pom.xml"], "merged", "a"),
                        (15, ["tools/old.sh"], "merged", "a"),
                        (1, ["tools/unmerged.sh"], "done", "a"),
                        (1, ["tools/other.sh"], "merged", "b"),
                    ]):
                        tid = desk.new_task(f"Release file change {i}", lane=lane)
                        desk.update(tid, state=state, merged=fixed_now - days * 86400, files=files)
                if row == 11:
                    # Rename detection records only the destination; merge's --no-renames sees both paths.
                    (self.repo / "tools").mkdir()
                    (self.repo / "tools" / "x.sh").write_text("echo release\n")
                    sh("git", "add", "tools/x.sh", cwd=self.repo)
                    sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "Release tool",
                       cwd=self.repo)
                    base = self.git_out("rev-parse", "HEAD")
                    sh("git", "mv", "tools/x.sh", "x.sh", cwd=self.repo)
                    sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "Move tool",
                       cwd=self.repo)
                    head = self.git_out("rev-parse", "HEAD")
                    files = self.git_out("diff", "--name-only", "--find-renames", base, head).splitlines()
                    self.assertEqual(files, ["x.sh"])
                    tid = desk.new_task("Move release tool", lane="a")
                    desk.update(tid, state="merged", merged=fixed_now - 86400, base=base, head=head, files=files)
                    from hansa.cli import _release_files_touched
                    self.assertEqual(_release_files_touched(self.repo, desk.meta(tid), ln), ["tools/x.sh"])
                if row == 12:
                    # A check on another execution lane and a verification do not supply m's timings.
                    for lane, kind, ran_on in (("a", "task", "a"), ("b", "verify", "m")):
                        tid = desk.new_task("Not m's task merge check", lane=lane, kind=kind)
                        desk.update(tid, merge_check_result={"ok": True, "exit": 0, "seconds": 999,
                                                             "at": fixed_now, "lane": ran_on})
                if row == 14:
                    tid = desk.new_task("Release tool change", lane="a")
                    desk.update(tid, state="merged", merged=fixed_now - 86400,
                                base=self.git_out("rev-parse", "HEAD"), head=self.git_out("rev-parse", "HEAD"),
                                files=["tools/x.sh"])
                    self.repo.rename(self.tmp / "moved-repo")

                def explain():
                    out = io.StringIO()
                    with contextlib.redirect_stdout(out), unittest.mock.patch("hansa.views.time.time", return_value=fixed_now):
                        main(["--desk", str(desk.root), "explain", "lane", "m" if row == 12 else "a"])
                    return out.getvalue()

                # Explaining derives the facts without changing the desk or adding any record.
                before = {p: p.read_bytes() for p in desk.root.rglob("*") if p.is_file()}
                shown = explain()
                self.assertEqual({p: p.read_bytes() for p in desk.root.rglob("*") if p.is_file()}, before)
                label = "merge check" if row == 5 else "task check"
                times = f"  {label} times (minutes, newest first): "
                if row in (1, 5):
                    self.assertIn(times + "1.67, 1.67, 1.67, 1.00, 1.00; median 1.67", shown)
                    self.assertIn(f"{label} is slower: last 3 average 1.67 minutes, the 5 before"
                                  " 1.00 minutes (1.7 times)", shown)
                    self.assertIn("Add a task to split the project's tests or run them in parallel", shown)
                    self.assertIn("use the merge check for what is slow (hansa help merge-check)", shown)
                elif row == 2:
                    self.assertIn(times + "1.17, 1.17, 1.17, 1.00, 1.00; median 1.17", shown)
                    self.assertNotIn("is slower", shown)
                elif row == 3:
                    self.assertIn("task check times: not enough runs yet", shown)
                    self.assertNotIn(times, shown)
                elif row == 4:
                    self.assertIn(times + "2.00, 1.00; median 1.50", shown)
                    self.assertIn("merge check times (minutes, newest first): 2.00, 1.00; median 1.50", shown)
                    self.assertNotIn("16.65", shown)
                elif row == 6:
                    self.assertIn("the merge check repeats the lane's check: every merge runs the lane's check again", shown)
                    self.assertIn("Use the lane's check for the quick tests and the merge check for the whole suite", shown)
                    # Equality also counts, with whitespace collapsed.
                    s["lanes"]["a"]["merge_check"] = "  make   lint "
                    self.assertEqual(desk.save_settings(s), [])
                    self.assertIn("the merge check repeats the lane's check", explain())
                elif row == 7:
                    self.assertNotIn("repeats the lane's check", shown)
                    # Positive control: the detector must exist, then remain silent again for unrelated commands.
                    s["lanes"]["a"]["merge_check"] = "make lint && make test-all"
                    self.assertEqual(desk.save_settings(s), [])
                    self.assertIn("repeats the lane's check", explain())
                    ln["merge_check"] = "make test-all"
                    self.assertEqual(desk.save_settings(s), [])
                    self.assertNotIn("repeats the lane's check", explain())
                elif row == 8:
                    self.assertIn("release_files matches (tasks merged in the last 14 days, requiring verification): "
                                  "tools/**: 4, pom.xml: 1", shown)
                    self.assertIn("release_files lists only what a release runs outside the sandbox", shown)
                    self.assertIn("an entry that 3 or more tasks touch may be wider than that (hansa help release-files)", shown)
                elif row == 9:
                    self.assertIn("merge check before merging: make test; in lane m's", shown)
                    self.assertNotIn("repeats the lane's check", shown)
                elif row == 10:
                    self.assertIn("in lane m's", shown)
                    self.assertIn("the merge check repeats the lane's check: every merge runs the lane's check again", shown)
                    self.assertIn("Use the lane's check for the quick tests and the merge check for the whole suite", shown)
                elif row == 11:
                    self.assertIn("release_files matches (tasks merged in the last 14 days, requiring verification): "
                                  "tools/**: 1", shown)
                    self.assertNotIn("an entry that 3 or more tasks touch", shown)
                elif row == 12:
                    self.assertIn("merge check times (minutes, newest first): 2.00, 1.00; median 1.50", shown)
                    self.assertNotIn("task check", shown)
                    self.assertNotIn("16.65", shown)
                elif row == 13:
                    self.assertIn("check after each task: none", shown)
                    self.assertIn("task check times: no check", shown)
                    self.assertNotIn("task check times: not enough runs yet", shown)
                elif row == 14:
                    self.assertIn("check after each task: make lint", shown)
                    self.assertIn("task check times: not enough runs yet", shown)
                    self.assertIn("merge check times: not enough runs yet", shown)
                    self.assertEqual([line for line in shown.splitlines() if "counts could not be read" in line],
                                     ["  release_files counts could not be read: No such file or directory."])
                    self.assertNotIn("release_files matches", shown)
                    self.assertIn("  standing instructions:", shown)

    def test_release_unreadable_repository_voids_cleanly(self):
        from hansa import release
        for missing in ("repository", "commit", "tree"):
            with self.subTest(missing=missing):
                self.with_release("true")
                r = release.ask(self.desk, "a")
                oid = self.git_out("rev-parse", r["commit"] + ("^{tree}" if missing == "tree" else ""))
                original = self.repo if missing == "repository" else self.repo / ".git" / "objects" / oid[:2] / oid[2:]
                moved = self.tmp / "unavailable"
                original.rename(moved)
                try:
                    self.assertIn("cannot be read", release.stale(self.desk, self.desk.settings(), r))
                    self.hansa("status")
                    answer = release.answer(self.desk, r["id"], True, commit=r["commit"])
                    self.assertIn("cannot be read", answer["void"])
                    self.assertEqual(release.get(self.desk, r["id"])["state"], "void")
                finally:
                    moved.rename(original)

    def test_release_request_with_unreadable_tree_is_refused_cleanly(self):
        from hansa import release
        self.with_release("true")
        sh("git", "update-ref", "refs/remotes/origin/main", "HEAD", cwd=self.repo)
        oid = self.git_out("rev-parse", "HEAD^{tree}")
        original = self.repo / ".git" / "objects" / oid[:2] / oid[2:]
        moved = self.tmp / "unavailable"
        original.rename(moved)
        try:
            self.assertIn("cannot be read", self.refused("release", "a"))
            self.assertEqual(release.releases(self.desk), [])
        finally:
            moved.rename(original)

    def test_release_output_and_metadata_arguments_are_accepted(self):
        from hansa import release
        self.commit_in_repo("deploy.sh", "echo deployed\n")
        (self.repo / "artefact").write_text("previous output\n")
        (self.repo / "0").touch()
        for command in ("tar -czf artefact deploy.sh", "rm -f artefact && sh ./deploy.sh", "cp deploy.sh artefact",
                        "cc -o artefact source.c", "tee artefact", "sed -i s/a/b/ artefact", "git add artefact",
                        "mytool --output artefact", "git commit -m artefact", "mytool --message 'sh artefact'",
                        "env FOO=bar tar -czf artefact deploy.sh", "env -u UNUSED git commit -m artefact",
                        "command cp deploy.sh artefact", "nice -n 5 cp deploy.sh artefact", "sh deploy.sh 0</dev/null",
                        "touch artefact; test -f artefact; [ -f artefact ]; echo artefact; printf %s artefact"):
            with self.subTest(command=command):
                self.with_release(command)
                self.assertEqual(release.ask(self.desk, "a")["state"], "waiting")

    def test_release_requests_require_named_repository_files_in_the_commit(self):
        from hansa import release
        script = self.repo / "publish.sh"
        (self.repo / ".git" / "info" / "exclude").write_text("publish.sh\n")
        script.write_bytes(b"binary\0input")
        (self.repo / "ops").mkdir()
        (self.repo / "ops" / "nested.sh").write_text("echo publish\n")
        for command in ("/bin/sh ./publish.sh", "bash -c 'sh publish.sh'", f"sh {script}",
                        "0</dev/null sh ./publish.sh", "env -u UNUSED sh publish.sh", "python3.9 publish.sh",
                        "sed -f ./publish.sh", "sed --file=./publish.sh", "awk -fpublish.sh",
                        ". ./publish.sh", "source publish.sh",
                        "touch marker.txt && sh ./publish.sh", "while [ -f marker.txt ]; do sh publish.sh; done",
                        "touch marker.txt\nsh ./publish.sh", "touch marker.txt;\nsh ./publish.sh",
                        "cd not-here; sh ./publish.sh", "(cd ops); sh ./publish.sh", "cd ops && sh nested.sh",
                        "sh -c 'cd ops; sh nested.sh'", 'echo "$(./publish.sh)"', "echo `./publish.sh`",
                        'true > "$(./publish.sh)"', "sh -c 'true;./publish.sh'"):
            with self.subTest(command=command):
                self.with_release(command)
                said = self.refused("release", "a")
                self.assertIn("ops/nested.sh" if "nested.sh" in command else "publish.sh", said)
                self.assertIn("commit", said)
        self.assertEqual(release.releases(self.desk), [])

    def test_release_answers_check_new_repository_inputs(self):
        from hansa import release
        for command in ("sh < ./publish.sh", "sh ./pub*.sh", "echo release <./publish.sh"):
            with self.subTest(command=command):
                self.with_release(command)
                r = release.ask(self.desk, "a")
                script = self.repo / "publish.sh"
                script.write_text("echo publish\n")
                answer = release.answer(self.desk, r["id"], True, commit=r["commit"])
                self.assertFalse(answer["ok"])
                self.assertIn("publish.sh", answer["void"])
                self.assertEqual(release.get(self.desk, r["id"])["state"], "void")
                self.assertTrue(release.stale(self.desk, self.desk.settings(), r, zh=True))
                script.unlink()

    def test_release_start_checks_repository_inputs_again(self):
        from hansa import release
        self.commit_in_repo("ops/inner/keep.txt", "keep directory\n")
        (self.repo / "current").symlink_to("ops/inner", target_is_directory=True)
        sh("git", "add", "current", cwd=self.repo)
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "Add directory link", cwd=self.repo)
        for word, path in (("./publish.sh", "publish.sh"), ("./publis[h].sh", "publish.sh"),
                           ("current/../publish.sh", "ops/publish.sh")):
            with self.subTest(word=word):
                self.with_release(f"sh {word}")
                r = release.ask(self.desk, "a")
                self.assertEqual(release.answer(self.desk, r["id"], True, commit=r["commit"]), {"ok": True})
                script = self.repo / path
                script.write_text("echo publish\n")
                with unittest.mock.patch.object(release, "_launch") as launch:
                    self.assertIsNone(release.start(self.desk, r["id"]))
                launch.assert_not_called()
                self.assertEqual(release.get(self.desk, r["id"])["state"], "void")
                script.unlink()
        self.assertEqual(self.events("release_started"), [])

    def test_release_repository_links_require_committed_paths(self):
        from hansa import release
        self.commit_in_repo("publish.sh", "echo publish\n")
        link = self.repo / "current.sh"
        link.symlink_to("publish.sh")
        self.with_release("sh ./current.sh")
        self.assertIn("current.sh", self.refused("release", "a"))
        sh("git", "add", "current.sh", cwd=self.repo)
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "Add link", cwd=self.repo)
        r = release.ask(self.desk, "a")
        self.assertEqual(release.answer(self.desk, r["id"], True, commit=r["commit"]), {"ok": True})
        (self.repo / "other.sh").write_text("echo other\n")
        link.unlink()
        link.symlink_to("other.sh")
        self.assertIn("other.sh", release.stale(self.desk, self.desk.settings(), r))
        self.assertIsNone(release.start(self.desk, r["id"]))

    def test_fixed_release_inputs_use_the_commit_rather_than_the_index(self):
        from hansa import release
        self.fixed_target("install", f"sh {self.repo / 'publish.sh'}", tick=False)
        (self.repo / "publish.sh").write_text("echo approved\n")
        sh("git", "add", "publish.sh", cwd=self.repo)
        self.assertIn("publish.sh", self.refused("release", "a", "install"))
        self.commit_in_repo("publish.sh", "echo approved\n")
        self.fixed_target("install", "sh ./publish.sh", tick=False)
        r = release.ask(self.desk, "a", target="install")
        self.assertEqual(release.answer(self.desk, r["id"], True, commit=r["commit"]), {"ok": True})
        (self.repo / "publish.sh").write_text("echo local\n")
        (self.repo / "unrelated.txt").write_text("local data\n")
        self.assertEqual(self.settle_release(Dispatcher(self.desk), r["id"])["state"], "done")
        log = (self.desk.state_dir / "releases" / f"{r['id']}.log").read_text()
        self.assertIn("approved", log)
        self.assertNotIn("local", log)
        self.fixed_target("install", f"sh ./publish.sh; sh {self.repo / 'publish.sh'}", tick=False)
        self.assertIn("publish.sh", self.refused("release", "a", "install"))

